// Otomatik üretildi (build.py). Elle düzenleme; kaynak: data1-3.py
window.KED = {"parts":[{"no":1,"hafta":"Hafta 1","grp":"Temeller","slayt":"ked-01-giris.pdf","title":"Dersin mantığı: giren = çıkan","ozet":"Bir gıda prosesine ne girer, ne çıkar? Kütlenin korunumu ve \"kuru madde kaçmaz\" fikri. Bütün dersin özü bu sayfada.","konu":[{"h":"Bu ders ne öğretiyor?","p":["Fabrikaya 1000 kg domates girdi. Kaç kg salça çıkar, ne kadar su uçurulur, kabuk ve çekirdek ne olur, buharlaştırmak için ne kadar enerji gerekir? Kütle ve enerji denklikleri bu soruları **sistematik olarak** cevaplamayı öğretir. Hoca bunu \"yalnızca matematik değil, prosesi okuyup karar verme aracı\" diye anlatıyor.","Her proses aynı şemaya oturur: **Hammadde → Proses → Ürün + Yan ürün + Atık**."],"tbl":{"head":["Soru","Hangi denklik?"],"rows":[["Ne kadar hammadde gerekli?","Kütle denkliği"],["Ne kadar ürün elde edilir?","Kütle denkliği"],["Ne kadar su uzaklaştırılır?","Kütle denkliği"],["Ne kadar atık oluşur?","Kütle denkliği"],["Ürünün bileşimi ne olur?","Kütle denkliği"],["Ne kadar ısıtma / soğutma / enerji gerekir?","Enerji denkliği"],["Proses nasıl optimize edilir?","Kütle + enerji denkliği"],["Maliyet ve sürdürülebilirlik?","Kütle + enerji + proses analizi"]]}},{"h":"Korunum ilkesi: giren = çıkan","p":["Madde yoktan var olmaz, vardan yok olmaz. Bir prosese giren toplam kütle, çıkan toplam kütleye eşittir (sistemde birikim yoksa)."],"f":["\\text{GİREN} = \\text{ÇIKAN}"],"p2":["**Peynir örneği:** Süt → Peynir + Peyniraltı suyu. Toplam kütleyi bilmek yetmez; su, yağ, protein, laktoz ve mineral **bileşenlerini de ayrı ayrı** takip etmek gerekir. Bu yüzden derste hem **toplam** hem **bileşen** denklikleri kurulur."]},{"h":"Kuru madde kaçmaz","p":["Kurutma ve evaporasyonda (buharlaştırmada) prosesten çıkan şey **yalnızca sudur**. Kuru madde (şeker, protein, lif, mineral…) olduğu yerde kalır. Ürün ağırlaşmaz, sadece suyunu kaybeder. Bu yüzden kuru madde miktarı başta ve sonda aynıdır:"],"f":["m_1 \\cdot x_1 = m_2 \\cdot x_2 \\qquad (x = \\text{kuru madde oranı})"],"p2":["**Nem + kuru madde = %100.** %85 nemli elma %15 kuru maddelidir. Soruda nem verilirse önce kuru maddeye çevir."],"anim":"kurutma"},{"h":"Dersin içeriği (vize konuları)","li":["**Boyutlar, ölçme sistemleri ve birimler:** SI, birim çevirme, boyutsal tutarlılık, boyutsuz sayılar (Hafta 2–4).","**Gıdaların bazı fiziksel nitelikleri:** konsantrasyon, yoğunluk, sıcaklık, ısı, basınç (Hafta 5–7).","**Kütle denkliği:** genel ilkeler, akış diyagramları, toplam ve bileşen denklikleri, gıda proseslerine uygulamalar (Hafta 8–9).","**Enerji denkliği:** entalpi, özgül ısı, faz değişimi, buhar tabloları. Slaytlarda henüz işlenmedi; vizede beklenmiyor."]}],"formul":[["Korunum (kararlı proses)","\\sum \\dot m_{\\text{giren}} = \\sum \\dot m_{\\text{çıkan}}"],["Kuru madde korunumu","m_1 x_1 = m_2 x_2"],["Ürün miktarı","m_{\\text{ürün}} = \\dfrac{m_{\\text{giren}}\\, x_{\\text{giren}}}{x_{\\text{ürün}}}"],["Uzaklaşan su","W = m_{\\text{giren}} - m_{\\text{ürün}}"],["Nem ve kuru madde","\\%\\,\\text{nem} + \\%\\,\\text{KM} = 100"]],"ornek":[{"id":"Örnek 1","src":"s.12","key":true,"anim":"kurutma","q":"%85 nem içeren 100 kg elma kurutularak %15 nemli ürün elde ediliyor. Kaç kg kuru elma elde edilir, ne kadar su uzaklaştırılır?","st":["Başlangıç kuru maddesi: elma %85 nemli → %15 kuru madde. $100 \\times 0{,}15 = 15$ kg kuru madde.","Kurutmada kuru madde değişmez. Üründe nem %15 → kuru madde %85.","$m_{\\text{ürün}} = 15 / 0{,}85 = 17{,}65$ kg.","Uzaklaşan su: $100 - 17{,}65 = 82{,}35$ kg."],"ans":"17,65 kg kuru elma, 82,35 kg su uzaklaşır."},{"id":"Örnek 2","src":"defter s.2","key":true,"q":"1 ton (%6 kuru maddeli) domates pulpu buharlaştırılarak %28 kuru maddeli salça yapılıyor. Kaç kg salça elde edilir?","st":["1 ton = 1000 kg. Kuru madde: $1000 \\times 0{,}06 = 60$ kg.","Salçada da 60 kg kuru madde var ve bu salçanın %28'i: $m = 60 / 0{,}28 = 214{,}3$ kg.","Buharlaşan su: $1000 - 214{,}3 = 785{,}7$ kg."],"ans":"≈ 214 kg salça (785,7 kg su buharlaşır)."}],"tuzak":["Nem yüzdesini kuru madde yüzdesi sanmak: \"%85 nem\" demek kuru madde **%15** demek.","Ürün miktarını $100 \\times 0{,}15$ diye bırakmak: 15 kg ürün değil, **ürünün içindeki kuru madde**. Ürün = 15 / 0,85.","Kurutmada kuru maddenin azaldığını sanmak. Uzaklaşan tek şey sudur."],"tekrar":["Her proses: Hammadde → Proses → Ürün + Yan ürün + Atık.","Kütle denkliği: ne kadar hammadde, ürün, su, atık, bileşim. Enerji denkliği: ne kadar ısıtma, soğutma, enerji.","Giren = Çıkan (birikim yoksa). Toplam yetmez, bileşenler (su, yağ, protein…) de ayrı izlenir.","Kurutma/evaporasyonda yalnız su çıkar, kuru madde sabit: $m_1x_1 = m_2x_2$.","Elma: 100 kg, %85 nem → 15 kg KM → 15/0,85 = 17,65 kg ürün; 82,35 kg su uçar."],"kisa":["Giren = Çıkan + Birikim.","Kuru madde kaçmaz: $m_1x_1 = m_2x_2$.","Nem% + KM% = 100."],"hap":["Kurutmada ve evaporasyonda yalnız su uzaklaşır; kuru madde sabit kalır.","100 kg %85 nemli elma → %15 nemli 17,65 kg kuru elma.","Toplam kütle denkliği tek başına yetmez; bileşen denklikleri de kurulur."]},{"no":2,"hafta":"Hafta 2","grp":"Temeller","slayt":"ked-02-birimler.pdf","title":"Boyutlar, birim sistemleri ve SI","ozet":"Boyut ile birim farkı, dört birim sistemi, SI temel ve türetilmiş birimleri (N, J, W, Pa), ön ekler ve birim yazım kuralları.","konu":[{"h":"Boyut ve birim","p":["**Boyut (dimension):** ölçülebilen ya da gözlenebilen fiziksel niteliktir: uzunluk, kütle, zaman, sıcaklık, enerji, alan, hacim…","**Birim (unit):** o boyutun kantitatif büyüklüğüdür. Uzunluğun birimi metre, zamanın birimi saniye. Her boyut mutlaka bir birimle verilir.","Bir şeyin **boyutu değişmez, birimi değişebilir.** 100 m² yüzeyden 400 W ısı geçiyorsa, 1 m²'den 4 W m⁻² ya da 14 400 J m⁻² h⁻¹ geçiyor demektir. Aynı şey, farklı birim."]},{"h":"Birim neden bu kadar önemli?","li":["**Mars Climate Orbiter (1999):** Yazılımı yapan firma itkiyi lbf·s (İngiliz) ile hesapladı, NASA ekibi N·s (SI) sandı. Uydu Mars atmosferinde parçalandı. Sadece birim uyumsuzluğu yüzünden yüz milyonlarca dolar gitti.","**Dondurulmuş meyve ihracatı:** Sözleşmede depolama 0 °F yazıyor. 0 °C'ye ayarlarsan ürün yolda çözülür: 0 °C = 32 °F, oysa 0 °F = −17,8 °C. Konteyner gümrükte reddedilir.","Birim hatası gıda güvenliğini, kaliteyi, kâr/zararı ve iş güvenliğini doğrudan etkiler."]},{"h":"Birim sistemleri","p":["cgs ve mks birlikte \"metrik sistem\" diye anılır. Endüstride mks, bilimde cgs daha yaygındır. 1960'ta 11. Ağırlık ve Ölçüler Genel Konferansı'nda **SI (Système International d'Unités)** oluşturuldu; bugün hem bilimde hem endüstride evrenseldir."],"tbl":{"head":["Sistem","Kullanım","Uzunluk","Kütle","Zaman","Sıcaklık","Kuvvet","Enerji"],"rows":[["ees (İngiliz müh.)","Endüstri","foot","lbm","s","°F","lbf","BTU"],["cgs (metrik)","Bilimsel","cm","g","s","°C","dyne","cal"],["mks (metrik)","Endüstri","m","kg","s","°C","kgf","kcal"],["SI","Evrensel","m","kg","s","K","N","J"]]}},{"h":"SI temel boyutları (7 tane)","p":["**Temel boyut** tek bir boyutu tanımlar; diğer her şey bunlardan türetilir."],"tbl":{"head":["Boyut","Birim","Simge"],"rows":[["Uzunluk","metre","m"],["Kütle","kilogram","kg"],["Zaman","saniye","s"],["Elektrik akımı","amper","A"],["Sıcaklık","kelvin","K"],["Madde miktarı","mol","mol"],["Işık şiddeti","kandil","cd"]]}},{"h":"Türetilmiş boyutlar","p":["Temel boyutların birleşimidir: alan = uzunluk × uzunluk, hız = uzunluk / zaman, yoğunluk = kütle / hacim."],"tbl":{"head":["Türetilmiş boyut","Tanım","SI birimi"],"rows":[["Alan","uzunluk × uzunluk","m²"],["Hacim","uzunluk³","m³"],["Hız","uzunluk / zaman","m/s"],["Yoğunluk","kütle / hacim","kg/m³"],["Konsantrasyon","mol / hacim","mol/m³"],["Özgül hacim","hacim / kütle","m³/kg"],["İvme","uzunluk / zaman²","m/s²"],["Kuvvet","kütle × ivme","kg·m/s²"]]},"anim":"birimagaci"},{"h":"Özel isimli türetilmiş birimler: N, J, W, Pa","p":["**Newton (kuvvet):** 1 kg kütleye 1 m/s² ivme kazandıran kuvvet."],"f":["F = m\\,a \\quad\\Rightarrow\\quad 1\\ \\text{N} = 1\\ \\text{kg}\\cdot\\text{m}\\,\\text{s}^{-2}","1\\ \\text{J} = 1\\ \\text{N}\\cdot\\text{m} = 1\\ \\text{kg}\\,\\text{m}^2\\,\\text{s}^{-2}","1\\ \\text{W} = 1\\ \\text{J/s} = 1\\ \\text{kg}\\,\\text{m}^2\\,\\text{s}^{-3}","1\\ \\text{Pa} = 1\\ \\text{N/m}^2 = 1\\ \\text{kg}\\,\\text{m}^{-1}\\,\\text{s}^{-2}"],"p2":["**Joule (enerji, iş, ısı):** 1 N'luk kuvvetin kendi doğrultusunda 1 m yol almasıyla yapılan iş. **İş, enerji ve ısı aynı boyuttadır**, birimi J.","**Watt (güç):** birim zamanda yapılan iş.","**Paskal (basınç):** birim alana etki eden kuvvet. Çok küçük olduğu için kPa (10³ Pa) ve bar kullanılır: **1 bar = 10⁵ Pa**.","Özgül ısı birimini temel birimlere indirme (slayt 24): $\\text{J/(kg K)} = \\text{N m/(kg K)} = \\dfrac{\\text{kg m}}{\\text{s}^2}\\cdot\\dfrac{\\text{m}}{\\text{kg K}} = \\text{m}^2/(\\text{s}^2\\,\\text{K})$."],"tbl":{"head":["Boyut","Özel isim","Simge","Diğer birimlerle","SI temel birimlerle"],"rows":[["Kuvvet","Newton","N","–","kg m s⁻²"],["Basınç","Paskal","Pa","N m⁻²","kg m⁻¹ s⁻²"],["Enerji, iş, ısı","Joule","J","N m","kg m² s⁻²"],["Güç","Watt","W","J s⁻¹","kg m² s⁻³"],["Elektrik potansiyeli","Volt","V","W A⁻¹","kg m² s⁻³ A⁻¹"]]}},{"h":"Ön ekler","tbl":{"head":["Ön ek","Simge","Çarpan","","Ön ek","Simge","Çarpan"],"rows":[["exa","E","10¹⁸","","desi","d","10⁻¹"],["peta","P","10¹⁵","","santi","c","10⁻²"],["tera","T","10¹²","","mili","m","10⁻³"],["giga","G","10⁹","","mikro","µ","10⁻⁶"],["mega","M","10⁶","","nano","n","10⁻⁹"],["kilo","k","10³","","piko","p","10⁻¹²"],["hekto","h","10²","","femto","f","10⁻¹⁵"],["deka","da","10¹","","atto","a","10⁻¹⁸"]]},"p2":["Büyütenlerden mega ve üstü **büyük harf** (M, G, T…), kilo ve altı küçük harf (k, h, da). $1\\ \\text{g} = 10^3\\ \\text{mg} = 10^6\\ \\mu\\text{g} = 10^9\\ \\text{ng} = 10^{12}\\ \\text{pg}$."]},{"h":"Dikkat edilmesi gerekenler (yazım kuralları)","li":["Sayısal değer **mutlaka birimiyle** yazılır. \"Tankta 1000 şıra var\" bir şey ifade etmez. Sayı + birim = fiziksel anlam.","Birim, sayı **0,1–1000** arasında kalacak şekilde seçilir: 10 000 cm yerine 100 m, 0,000001 m yerine 1 µm, 10 000 Pa yerine 10 kPa.","Sayılara uygulanan işlem birimlere de uygulanır: $(4\\ \\text{m})^2 = 16\\ \\text{m}^2$.","Toplama ve çıkarma **yalnızca aynı birimdeki** değerlerle yapılır.","Eşitliğin iki tarafı boyutça aynı olmalı. Bu, eşitliği kontrol etmenin de yoludur.","Simgeler küçük harfle yazılır; özel isimden türemişse ilk harf büyük: m, kg, s ama **Pa, N, J, W, K**.","Simgelerin sonuna nokta konmaz. Saniye **s** (sn değil), gram **g** (gr değil), litre **L** (Lt değil)."]},{"h":"Problem çözerken yapılan başlıca hatalar (slayt 32)","li":["Birim dönüştürme hataları.","Birim dönüştürmeden verileri kullanmak.","Matematiksel işlem hataları.","Soruda verilen **bütün** verileri kullanmaya çalışmak (bazı veriler fazladır).","Sonucun birimini yazmamak.","Sonucu yorumlamamak."]}],"formul":[["Kuvvet","1\\ \\text{N} = 1\\ \\text{kg m s}^{-2}"],["Enerji (iş, ısı)","1\\ \\text{J} = 1\\ \\text{N m} = 1\\ \\text{kg m}^2\\text{s}^{-2}"],["Güç","1\\ \\text{W} = 1\\ \\text{J s}^{-1}"],["Basınç","1\\ \\text{Pa} = 1\\ \\text{N m}^{-2} = 1\\ \\text{kg m}^{-1}\\text{s}^{-2}"],["Bar","1\\ \\text{bar} = 10^5\\ \\text{Pa}"],["Özgül ısı (temel birim)","\\text{J/(kg K)} = \\text{m}^2/(\\text{s}^2\\,\\text{K})"],["Kütle ön ekleri","1\\ \\text{g} = 10^3\\ \\text{mg} = 10^6\\ \\mu\\text{g} = 10^9\\ \\text{ng}"]],"ornek":[{"id":"Örnek 1","src":"defter ödevi","key":true,"q":"cgs sisteminde yoğunluğu 1,05 g/cm³ olan bir maddenin yoğunluğunu SI biriminde yazınız.","st":["SI'da yoğunluk kg/m³. Çevirme faktörleri: 1 kg = 1000 g, 1 m = 100 cm → 1 m³ = 10⁶ cm³.","$1{,}05\\ \\dfrac{\\text{g}}{\\text{cm}^3}\\times\\dfrac{1\\ \\text{kg}}{1000\\ \\text{g}}\\times\\dfrac{10^6\\ \\text{cm}^3}{1\\ \\text{m}^3} = 1050\\ \\text{kg/m}^3$"],"ans":"1050 kg/m³ (kısa yol: g/cm³ × 1000 = kg/m³)."},{"id":"Örnek 2","src":"s.9","q":"100 m²'lik bir yüzeyden 400 W ısı geçiyor. Bunu 1 m² için W/m² ve J/(m² h) olarak yazınız.","st":["$400\\ \\text{W} / 100\\ \\text{m}^2 = 4\\ \\text{W/m}^2$.","$1\\ \\text{W} = 1\\ \\text{J/s}$ ve $1\\ \\text{h} = 3600\\ \\text{s}$: $4\\ \\dfrac{\\text{J}}{\\text{s m}^2}\\times 3600\\ \\dfrac{\\text{s}}{\\text{h}} = 14\\,400\\ \\text{J m}^{-2}\\text{h}^{-1}$."],"ans":"4 W/m² = 14 400 J m⁻² h⁻¹ (boyut aynı, birim farklı)."},{"id":"Örnek 3","src":"s.21–23","q":"Joule, Watt ve Paskal birimlerini SI temel birimleriyle (kg, m, s) ifade ediniz.","st":["$\\text{J} = \\text{N}\\cdot\\text{m} = (\\text{kg m s}^{-2})\\cdot\\text{m} = \\text{kg m}^2\\text{s}^{-2}$","$\\text{W} = \\text{J/s} = \\text{kg m}^2\\text{s}^{-3}$","$\\text{Pa} = \\text{N/m}^2 = (\\text{kg m s}^{-2})/\\text{m}^2 = \\text{kg m}^{-1}\\text{s}^{-2}$"],"ans":"J = kg m² s⁻², W = kg m² s⁻³, Pa = kg m⁻¹ s⁻²."}],"tuzak":["\"gr\", \"sn\", \"Lt\" yazmak yanlış: doğrusu **g, s, L**.","Sonuca birim yazmamak puan kaybettirir.","Pa'yı küçük harfle \"pa\" yazmak; özel isimden gelen birimler büyük harfle başlar (Pa, N, J, W, K).","Sıcaklıkta SI birimi °C değil **K**'dir; kuvvette kgf değil **N**.","Mega (M) ile mili (m) karışır: büyük M = 10⁶, küçük m = 10⁻³."],"tekrar":["Boyut = ne ölçüldüğü (uzunluk); birim = nasıl ölçüldüğü (metre). Boyut değişmez, birim değişir.","Sistemler: ees (ft, lbm, s, °F, lbf, BTU), cgs (cm, g, s, °C, dyne, cal), mks (m, kg, s, °C, kgf, kcal), SI (m, kg, s, K, N, J).","7 temel SI boyutu: m, kg, s, A, K, mol, cd.","N = kg m/s², J = N m, W = J/s, Pa = N/m². 1 bar = 10⁵ Pa.","Ön ekler: k 10³, M 10⁶, G 10⁹ ; m 10⁻³, µ 10⁻⁶, n 10⁻⁹.","Yazım: s, g, L (sn, gr, Lt değil); nokta yok; özel isimden gelen birim büyük harf.","Mars Orbiter: lbf·s ↔ N·s karışıklığı. 0 °F = −17,8 °C."],"kisa":["SI: m, kg, s, K, mol, A, cd.","N = kg m s⁻², J = N m, W = J s⁻¹, Pa = N m⁻².","Yazım: s, g, L; Pa, N, J büyük harf."],"hap":["İş, enerji ve ısı aynı boyuttadır; birimi Joule.","1 bar = 10⁵ Pa ≈ 1 atm.","0 °F = −17,8 °C; 0 °C = 32 °F.","Birim, sayı 0,1–1000 arasında kalacak şekilde seçilir (10 kPa, 10 000 Pa değil).","J/(kg K) = m²/(s² K)."]},{"no":3,"hafta":"Hafta 3","grp":"Temeller","slayt":"ked-03-birim-cevirme.pdf","title":"Birim çevirme","ozet":"Çevirme faktörü yöntemi, İngiliz birimleri ve sınavın klasik soruları: BTU, ft, lbm, °F içeren birimleri SI'ya çevirmek, Q = m·cp·ΔT.","konu":[{"h":"Boyutlu eşitlik","p":["Sayısal değeri ve birimini birlikte içeren eşitliğe **boyutlu eşitlik** denir. Örnek: $10\\ \\text{BTU/(h ft °F)} = 17{,}3\\ \\text{J/(s m K)}$.","Sayılara hangi işlem uygulanıyorsa birimlere de aynısı uygulanır:"],"f":["10\\ \\text{kg} - 5\\ \\text{kg} = 5\\ \\text{kg} \\qquad (5\\ \\text{m})^2 = 25\\ \\text{m}^2","(10\\ \\tfrac{\\text{J}}{\\text{kg °C}})(5\\ \\text{kg})(15\\ \\text{°C}) = 750\\ \\text{J}"]},{"h":"Çevirme faktörü yöntemi (4 adım)","li":["Eşitliğin **soluna hedef birimi** yaz.","Sağına **çevrilecek değeri ve birimini** yaz.","Sağ tarafa birim çevirme tablosundan bulduğun **çevirme katsayılarını çarpım olarak** ekle. Her kesir 1'e eşittir (ör. $\\frac{1055\\ \\text{J}}{1\\ \\text{BTU}}$).","Kesirleri, istemediğin birim payda ve paydada **birbirini götürecek** şekilde diz. Sonunda yalnız hedef birim kalır."],"p2":["Altın kural: götürmek istediğin birim payda ise yeni kesirde paydaya, paydadaysa paya yazılır."],"anim":"cevirme"},{"h":"İngiliz ölçü birimleri (çevirme tablosu)","tbl":{"head":["Boyut","Birim","Eşdeğeri"],"rows":[["Kütle","1 lbm (pound)","0,4536 kg (slaytta 0,454)"],["Kütle","1 oz (ounce)","0,0625 lbm = 0,0284 kg"],["Kütle","1 stone","14 lbm = 6,35 kg"],["Hacim","1 gallon (gal)","3,785 L = 4 quart"],["Hacim","1 quart (qt)","2 pint = 0,946 L = 32 fl oz"],["Hacim","1 pint (pt)","16 fl oz = 0,473 L"],["Uzunluk","1 inch (in)","2,54 cm = 1/12 ft"],["Uzunluk","1 foot (ft)","12 in = 30,48 cm (1 m = 3,28 ft)"],["Uzunluk","1 yard (yd)","3 ft = 91,44 cm"],["Uzunluk","1 mile (mi)","1760 yd = 1609 m"],["Enerji","1 BTU","1,05506 kJ = 1055,06 J (1 kJ = 0,9478 BTU)"],["Zaman","1 h","3600 s"],["Sıcaklık farkı","1 °F (Δ)","5/9 °C = 5/9 K"],["Sıcaklık farkı","1 °C (Δ)","1 K"]]}},{"h":"Paydada °F varsa ne olacak?","p":["Isıl iletkenlik (BTU/h ft °F), özgül ısı (BTU/lbm °F) gibi birimlerde °F bir **sıcaklık farkını** gösterir. Fark çevrilirken +32 yapılmaz; sadece ölçek değişir: **1 K'lik fark = 1,8 °F'lik fark**.","Paydadaki °F'yi götürmek için kesri $\\dfrac{1{,}8\\ \\text{°F}}{1\\ \\text{K}}$ olarak yazarsın. Yani **paydada °F varsa sonuç 1,8 ile çarpılır.**"],"f":["\\frac{1}{\\text{°F}} = \\frac{1}{\\text{°F}}\\times\\frac{1{,}8\\ \\text{°F}}{1\\ \\text{K}} = \\frac{1{,}8}{\\text{K}}"]},{"h":"Hissedilir ısı: Q = m·cp·ΔT","p":["Faz değişimi olmadan bir maddenin sıcaklığını değiştirmek için gereken ısı:"],"f":["Q = m\\, c_p\\, \\Delta T"],"p2":["$Q$: kazanılan ya da kaybedilen ısı (BTU veya J); $m$: kütle (lbm veya kg); $c_p$: özgül ısı (BTU/lbm °F veya J/kg K); $\\Delta T$: sıcaklık değişimi (°F veya K).","Güç–enerji bağı: $\\text{Güç} = \\text{Enerji}/\\text{zaman}$, $1\\ \\text{W} = 1\\ \\text{J/s}$, **$1\\ \\text{kWh} = 3{,}6\\times 10^6\\ \\text{J}$**. Süre bulmak için $t = Q / \\text{Güç}$.","Suyun özgül ısısı 1 BTU/lbm °F = 1 kcal/kg °C = 4,186 kJ/kg K; yoğunluğu 1 g/cm³ = 1 kg/L."]}],"formul":[["Enerji","1\\ \\text{BTU} = 1055\\ \\text{J} = 1{,}055\\ \\text{kJ}"],["Kütle","1\\ \\text{lbm} = 0{,}4536\\ \\text{kg}"],["Uzunluk","1\\ \\text{ft} = 0{,}3048\\ \\text{m} = 12\\ \\text{in},\\ \\ 1\\ \\text{in} = 2{,}54\\ \\text{cm}"],["Hacim","1\\ \\text{gal} = 3{,}785\\ \\text{L} = 4\\ \\text{qt} = 8\\ \\text{pt}"],["Zaman","1\\ \\text{h} = 3600\\ \\text{s}"],["Sıcaklık farkı","1\\ \\text{K} = 1\\ \\text{°C} = 1{,}8\\ \\text{°F}\\ \\ (\\Delta)"],["kWh","1\\ \\text{kWh} = 3{,}6\\times10^6\\ \\text{J}"],["Hissedilir ısı","Q = m\\,c_p\\,\\Delta T"],["Güç","P = Q/t,\\quad 1\\ \\text{W} = 1\\ \\text{J/s}"],["Hazır çarpanlar","\\tfrac{\\text{BTU}}{\\text{h ft °F}}\\times 1{,}731 = \\tfrac{\\text{W}}{\\text{m K}},\\quad \\tfrac{\\text{BTU}}{\\text{lbm °F}}\\times 4187 = \\tfrac{\\text{J}}{\\text{kg K}}"]],"ornek":[{"id":"Örnek 1","src":"s.14–18","key":true,"anim":"cevirme","q":"10 BTU/(h ft °F) düzeyindeki ısıl iletkenlik katsayısını SI birimine (J/(s m K)) çeviriniz.","st":["Çevirme katsayıları: 1 BTU = 1055 J, 1 h = 3600 s, 1 ft = 0,3048 m, 1 °F (fark) = 5/9 K.","$\\dfrac{\\text{J}}{\\text{s m K}} = 10\\ \\dfrac{\\text{BTU}}{\\text{h ft °F}}\\times\\dfrac{1055\\ \\text{J}}{1\\ \\text{BTU}}\\times\\dfrac{1\\ \\text{h}}{3600\\ \\text{s}}\\times\\dfrac{1\\ \\text{ft}}{0{,}3048\\ \\text{m}}\\times\\dfrac{1{,}8\\ \\text{°F}}{1\\ \\text{K}}$","BTU, h, ft, °F birbirini götürür. Sayılar: $10\\times1055\\times1{,}8 / (3600\\times0{,}3048) = 17{,}3$."],"ans":"17,3 J/(s m K) = 17,3 W/(m K)."},{"id":"Örnek 2","src":"s.19–20","key":true,"anim":"cevirme:cp","q":"%45 çözünmüş madde içeren portakal suyu konsantresinin özgül ısısı cp = 0,64 BTU/lbm °F. SI birimine (J/kg K) çeviriniz.","st":["$\\dfrac{\\text{J}}{\\text{kg K}} = 0{,}64\\ \\dfrac{\\text{BTU}}{\\text{lbm °F}}\\times\\dfrac{1055\\ \\text{J}}{1\\ \\text{BTU}}\\times\\dfrac{1\\ \\text{lbm}}{0{,}4536\\ \\text{kg}}\\times\\dfrac{1{,}8\\ \\text{°F}}{1\\ \\text{K}}$","$0{,}64\\times1055\\times1{,}8/0{,}4536 = 2679$."],"ans":"cp ≈ 2679 J/(kg K) ≈ 2,68 kJ/(kg K)."},{"id":"Örnek 3","src":"s.21–22","q":"21 °C'deki salamın yüzey ısı transfer katsayısı hs = 210 BTU/(ft² h °F). SI birimine (J/(m² s K)) çeviriniz.","st":["$210\\times\\dfrac{1055\\ \\text{J}}{\\text{BTU}}\\times\\dfrac{1\\ \\text{ft}^2}{(0{,}3048\\ \\text{m})^2}\\times\\dfrac{1\\ \\text{h}}{3600\\ \\text{s}}\\times\\dfrac{1{,}8\\ \\text{°F}}{1\\ \\text{K}}$","Dikkat: ft² olduğu için 0,3048'in **karesi** alınır: 0,09290 m².","$210\\times1055\\times1{,}8/(0{,}09290\\times3600) = 1192$."],"ans":"hs ≈ 1192 J/(m² s K) = 1192 W/(m² K)."},{"id":"Örnek 4","src":"s.23–24","q":"İnek sütünün yoğunluğu 64,5 lbm/ft³. SI birimine çeviriniz.","st":["$64{,}5\\ \\dfrac{\\text{lbm}}{\\text{ft}^3}\\times\\dfrac{0{,}4536\\ \\text{kg}}{1\\ \\text{lbm}}\\times\\dfrac{1\\ \\text{ft}^3}{(0{,}3048\\ \\text{m})^3}$","$(0{,}3048)^3 = 0{,}028317\\ \\text{m}^3$. $64{,}5\\times0{,}4536/0{,}028317 = 1033$."],"ans":"≈ 1033 kg/m³."},{"id":"Örnek 5","src":"s.25–26","q":"173 cm boyu feet ve inch olarak ifade ediniz.","st":["$173\\ \\text{cm}\\times\\dfrac{1\\ \\text{in}}{2{,}54\\ \\text{cm}} = 68{,}11\\ \\text{in}$","$68{,}11\\ \\text{in}\\times\\dfrac{1\\ \\text{ft}}{12\\ \\text{in}} = 5{,}68\\ \\text{ft}$","Tam kısım 5 ft; kalan $0{,}68\\ \\text{ft}\\times 12 = 8{,}16\\ \\text{in}$."],"ans":"5 ft 8 in (5′ 8″)."},{"id":"Örnek 6","src":"s.27–28","q":"40 L'lik benzin deposunu gallon, pint ve fluid ounce olarak ifade ediniz.","st":["$40\\ \\text{L}\\times\\dfrac{1\\ \\text{gal}}{3{,}79\\ \\text{L}} = 10{,}55\\ \\text{gal}$ (slayt 10,6 diye yuvarlıyor).","$10{,}55\\ \\text{gal}\\times 4\\ \\tfrac{\\text{qt}}{\\text{gal}}\\times 2\\ \\tfrac{\\text{pt}}{\\text{qt}} = 84{,}4\\ \\text{pt}$","$84{,}4\\ \\text{pt}\\times 16\\ \\tfrac{\\text{fl oz}}{\\text{pt}} = 1350{,}4\\ \\text{fl oz}$"],"ans":"≈ 10,6 gal = 84,4 pint = 1350 fl oz."},{"id":"Örnek 7","src":"s.29–30","key":true,"anim":"cevirme:firin","q":"Pasta fırınının duvarlarından saatte 6500 BTU enerji kayboluyor. Kek 0,5 h sabit sıcaklıkta pişecek. Bu sürede verilmesi gereken enerjiyi kWh olarak bulunuz.","st":["Kaybolan enerji kadar enerji verilmeli: $6500\\ \\tfrac{\\text{BTU}}{\\text{h}}\\times 0{,}5\\ \\text{h} = 3250\\ \\text{BTU}$.","$3250\\ \\text{BTU}\\times\\dfrac{1055\\ \\text{J}}{\\text{BTU}}\\times\\dfrac{1\\ \\text{W s}}{1\\ \\text{J}}\\times\\dfrac{1\\ \\text{kW}}{1000\\ \\text{W}}\\times\\dfrac{1\\ \\text{h}}{3600\\ \\text{s}}$","$= 3\\,428\\,750\\ \\text{J}/3{,}6\\times10^6 = 0{,}952\\ \\text{kWh}$."],"ans":"0,952 kWh."},{"id":"Örnek 8","src":"s.31–32","key":true,"q":"Özgül ısısı 0,8 BTU/lbm °F olan 10 lbm etin sıcaklığını 40 °F'tan 130 °F'a çıkarmak için gereken ısıyı Wh olarak bulunuz. 200 W'lık mikrodalga fırında ne kadar sürede pişer?","st":["$\\Delta T = 130 - 40 = 90\\ \\text{°F}$. $Q = m c_p \\Delta T = 10\\times0{,}8\\times90 = 720\\ \\text{BTU}$.","$720\\ \\text{BTU}\\times1055\\ \\tfrac{\\text{J}}{\\text{BTU}} = 759\\,600\\ \\text{J}$; $\\div 3600\\ \\tfrac{\\text{J}}{\\text{Wh}} = 211\\ \\text{Wh}$.","Süre: $t = Q/P = 211\\ \\text{Wh}/200\\ \\text{W} = 1{,}055\\ \\text{h} \\approx 63\\ \\text{dk}$."],"ans":"211 Wh; yaklaşık 1,06 saat (≈ 63 dakika)."},{"id":"Örnek 9","src":"s.33","key":true,"q":"100 galon suyun sıcaklığını 60 °F'tan 100 °F'a çıkarmak için gereken ısıyı kWh olarak bulunuz (cp = 1 BTU/lbm °F, ρ = 1 g/cm³).","st":["Hacim → kütle: $100\\ \\text{gal}\\times3{,}79\\ \\tfrac{\\text{L}}{\\text{gal}} = 379\\ \\text{L}$ → ρ = 1 kg/L ile 379 kg.","$379\\ \\text{kg}/0{,}4536 = 835{,}5\\ \\text{lbm}$.","$Q = 835{,}5\\times1\\times(100-60) = 33\\,422\\ \\text{BTU}$.","$33\\,422\\times1055 = 3{,}526\\times10^7\\ \\text{J}$; $\\div 3{,}6\\times10^6 = 9{,}79\\ \\text{kWh}$."],"ans":"≈ 9,79 kWh (slayt cevabı 9,794; 3,785 L/gal ile 9,78 çıkar)."}],"tuzak":["Paydadaki °F'yi unutmak: sonuç **1,8 ile çarpılmalı** (5/9 ile bölmek aynı şey).","Sıcaklık **farkını** çevirirken +32 eklemek. Fark çevrilirken sadece 1,8 çarpanı vardır.","ft² veya ft³ olduğunda 0,3048'in karesini/küpünü almayı unutmak.","kWh'yi J'ye çevirirken 3600 değil **3,6 × 10⁶** kullanmak gerekir (kW × h = 1000 W × 3600 s).","Hacimle verilen suyu kütleye çevirmeden Q = m cp ΔT'ye koymak.","lbm (kütle) ile lbf (kuvvet) aynı şey değil."],"tekrar":["Hedef birim solda, verilen değer sağda; çevirme kesirlerini istenmeyen birim sadeleşecek şekilde çarp.","1 BTU = 1055 J · 1 lbm = 0,4536 kg · 1 ft = 0,3048 m = 12 in · 1 in = 2,54 cm · 1 gal = 3,785 L · 1 h = 3600 s.","Sıcaklık farkı: 1 K = 1 °C = 1,8 °F. Paydada °F varsa × 1,8.","ft² → (0,3048)², ft³ → (0,3048)³.","Q = m cp ΔT. 1 kWh = 3,6 × 10⁶ J. Süre = enerji / güç.","10 BTU/(h ft °F) = 17,3 W/(m K) · 0,64 BTU/(lbm °F) = 2679 J/(kg K) · 64,5 lbm/ft³ = 1033 kg/m³.","Fırın: 6500 BTU/h × 0,5 h = 3250 BTU = 0,952 kWh. Et: 720 BTU = 211 Wh → 200 W'ta 1,055 h."],"kisa":["Hedef birim sola, kesirler sağa; birimler sadeleşsin.","1 BTU = 1055 J; 1 lbm = 0,4536 kg; 1 ft = 0,3048 m; 1 gal = 3,785 L.","Paydada °F → × 1,8.","Q = m cp ΔT; 1 kWh = 3,6 MJ."],"hap":["BTU/(h ft °F) → W/(m K): × 1,731.","BTU/(lbm °F) → J/(kg K): × 4187.","lbm/ft³ → kg/m³: × 16,02.","1 kWh = 3 600 000 J.","1 K'lik fark = 1,8 °F'lik fark.","1 gal = 4 qt = 8 pt = 128 fl oz."]},{"no":4,"hafta":"Hafta 4","grp":"Temeller","slayt":"ked-04-boyutsal-tutarlilik.pdf","title":"Boyutsal tutarlılık ve boyutsuz sayılar","ozet":"Bir eşitliğin iki tarafı aynı birimde olmalı. Van der Waals sabitlerinin birimi, Re, Nu, Pr, Fo, Bi sayıları ve ampirik bir eşitliği başka birim sistemine çevirme.","konu":[{"h":"Eşitliklerin boyutsal tutarlılığı","p":["Bütün eşitliklerin **iki tarafı aynı boyutta ve birimde** olmalıdır. Kontrol etmek kolay: değişkenlerin birimlerini aynı sistemde yerine koy, sadeleştir, iki tarafı karşılaştır.","Hesaba başlamadan önce sağdaki ve soldaki birimlerin eşitliği kontrol edilir. **Birimler uyuşmuyorsa formül ya da çözüm yanlıştır.**"]},{"h":"Örnek: konvektif ısı transferi Q = h A ΔT","f":["\\underbrace{Q}_{\\text{W}} = \\underbrace{h}_{\\text{W/(m}^2\\text{K)}}\\ \\underbrace{A}_{\\text{m}^2}\\ \\underbrace{\\Delta T}_{\\text{K}} \\;\\Rightarrow\\; \\text{W} = \\frac{\\text{W}}{\\text{m}^2\\,\\text{K}}\\cdot\\text{m}^2\\cdot\\text{K} = \\text{W}"],"p2":["m² K pay ve paydada birbirini götürür; iki tarafta da W kalır. Eşitlik boyutsal olarak tutarlıdır."]},{"h":"Van der Waals eşitliği: sabitlerin birimi","f":["\\left(P + \\frac{n^2 a}{V^2}\\right)(V - n b) = n R T"],"p2":["Mantık: **toplanan ve çıkarılan terimler aynı birimde olmalı.**","$\\frac{n^2a}{V^2}$ basınca ekleniyor → birimi basınç (N/m²): $a = \\dfrac{\\text{N}}{\\text{m}^2}\\cdot\\dfrac{(\\text{m}^3)^2}{(\\text{kmol})^2} = \\dfrac{\\text{N m}^4}{\\text{kmol}^2}$.","$nb$ hacimden çıkarılıyor → birimi m³: $b = \\dfrac{\\text{m}^3}{\\text{kmol}}$.","Sol taraf basınç × hacim = N m. Sağ taraf $nRT$ → $R = \\dfrac{\\text{N m}}{\\text{kmol K}} = \\dfrac{\\text{J}}{\\text{kmol K}}$."]},{"h":"Boyutsuz sayılar","p":["Akışkanlar mekaniği, ısı ve kütle transferinde çok kullanılır. Birimleri yerine koyunca hepsi sadeleşir."],"tbl":{"head":["Sayı","Tanım","Değişkenler"],"rows":[["Reynolds (Re)","D V ρ / μ","D çap (m), V hız (m/s), ρ yoğunluk (kg/m³), μ viskozite (kg/m s)"],["Nusselt (Nu)","h D / k","h ısı transfer katsayısı (W/m² K), k ısıl iletkenlik (W/m K)"],["Prandtl (Pr)","cp μ / k","cp özgül ısı (J/kg K)"],["Fourier (Fo)","α t / L²","α ısıl yayınım (m²/s), t zaman (s), L kalınlık (m)"],["Biot (Bi)","h L / k","L kalınlık (m)"]]},"f":["\\text{Re} = \\frac{D V \\rho}{\\mu} = \\frac{\\text{m}\\cdot\\frac{\\text{m}}{\\text{s}}\\cdot\\frac{\\text{kg}}{\\text{m}^3}}{\\frac{\\text{kg}}{\\text{m s}}} = \\text{birimsiz}"],"p2":["Viskozite birimi: SI'da kg/(m s) = Pa s; cgs'de g/(cm s) = **Poise (P)**. $1\\ \\text{P} = 100\\ \\text{cP}$, $1\\ \\text{cP} = 10^{-3}\\ \\text{Pa s}$ (suyun viskozitesi ≈ 1 cP).","Ek bilgi (slaytta yok): boruda Re < 2100 laminer, Re > 4000 türbülanslı akış. Slayttaki süt Re = 50 000 ile türbülanslı."],"anim":"resayi"},{"h":"Boyutsuz eşitlikler ve birimli sabitler","p":["Bütün terimleri boyutsuz olan eşitliklere boyutsuz eşitlik denir. **Dittus–Boelter:** $\\text{Nu} = 0{,}023\\,\\text{Re}^{0{,}8}\\,\\text{Pr}^{0{,}3}$. Terimler boyutsuz olduğu için 0,023'ün de birimi yoktur ve her birim sisteminde aynıdır.","Ama birçok sabitin **birimi vardır** ve sayısal değeri birim sistemine göre değişir. Arrhenius eşitliğindeki gaz sabiti:"],"f":["k = k_0\\, e^{-E_a/RT} \\qquad R = 8{,}314\\ \\tfrac{\\text{J}}{\\text{mol K}} = 1{,}987\\ \\tfrac{\\text{cal}}{\\text{mol K}} = 0{,}0821\\ \\tfrac{\\text{L atm}}{\\text{mol K}}"]},{"h":"Ampirik bir eşitliği başka birim sistemine çevirme","p":["Hava ile katı gıda arasındaki ısı transfer katsayısı İngiliz sisteminde $h = 0{,}0128\\,G^{0{,}8}$ (G: lbm/(ft² h), h: BTU/(ft² h °F)). Eşitlik tutarlı olsun diye **0,0128'in bir birimi olmalı**:"],"f":["[0{,}0128] = \\frac{\\text{BTU/(ft}^2\\,\\text{h °F)}}{(\\text{lbm/(ft}^2\\,\\text{h}))^{0{,}8}} = \\frac{\\text{BTU}}{\\text{h}^{0{,}2}\\,\\text{ft}^{0{,}4}\\,\\text{lbm}^{0{,}8}\\,\\text{°F}}"],"p2":["Bu birimi SI'ya çevirince (J, s, m, kg, K) sabit **14,31** olur: SI'da $h = 14{,}31\\,G^{0{,}8}$ (G: kg/(m² s), h: W/(m² K)). Yöntem: sabitin birimini bul → birim çevirme yap."]}],"formul":[["Reynolds","\\text{Re} = \\frac{D V \\rho}{\\mu}"],["Nusselt","\\text{Nu} = \\frac{h D}{k}"],["Prandtl","\\text{Pr} = \\frac{c_p \\mu}{k}"],["Fourier","\\text{Fo} = \\frac{\\alpha t}{L^2}"],["Biot","\\text{Bi} = \\frac{h L}{k}"],["Dittus–Boelter","\\text{Nu} = 0{,}023\\,\\text{Re}^{0{,}8}\\text{Pr}^{0{,}3}"],["Viskozite","1\\ \\text{cP} = 10^{-3}\\ \\text{Pa s},\\ \\ 1\\ \\text{P} = 1\\ \\text{g/(cm s)} = 100\\ \\text{cP}"],["Van der Waals birimleri","a = \\tfrac{\\text{N m}^4}{\\text{kmol}^2},\\ b = \\tfrac{\\text{m}^3}{\\text{kmol}},\\ R = \\tfrac{\\text{N m}}{\\text{kmol K}}"],["Gaz sabiti","R = 8{,}314\\ \\tfrac{\\text{J}}{\\text{mol K}} = 1{,}987\\ \\tfrac{\\text{cal}}{\\text{mol K}} = 0{,}0821\\ \\tfrac{\\text{L atm}}{\\text{mol K}}"]],"ornek":[{"id":"Örnek 1","src":"s.4–5","q":"Q = h A ΔT eşitliğinin boyutsal olarak tutarlı olduğunu gösteriniz (Q: J/s, h: W/m² K, A: m², ΔT: K).","st":["Sağ taraf: $\\dfrac{\\text{W}}{\\text{m}^2\\text{K}}\\cdot\\text{m}^2\\cdot\\text{K} = \\text{W}$.","Sol taraf: J/s = W.","İki taraf aynı: W = W."],"ans":"Tutarlı; iki tarafta da W kalır."},{"id":"Örnek 2","src":"s.6–9","key":true,"q":"Van der Waals eşitliğinde a, b ve R sabitlerinin birimlerini bulunuz (P: N/m², V: m³, n: kmol, T: K).","st":["$n b$ hacimden çıkarılıyor → $\\text{kmol}\\cdot b = \\text{m}^3$ → $b = \\text{m}^3/\\text{kmol}$.","$n^2a/V^2$ basınca ekleniyor → $\\dfrac{\\text{kmol}^2\\, a}{\\text{m}^6} = \\dfrac{\\text{N}}{\\text{m}^2}$ → $a = \\text{N m}^4/\\text{kmol}^2$.","Sol taraf (basınç)(hacim) = N m. $nRT$ = N m → $R = \\dfrac{\\text{N m}}{\\text{kmol K}}$."],"ans":"a = N m⁴/kmol², b = m³/kmol, R = N m/(kmol K) = J/(kmol K)."},{"id":"Örnek 3","src":"s.12–15","key":true,"q":"Süt Re = 50 000 ile türbülanslı akıyor. 1 in çaplı boruda hız 13,5 ft/s, 294 K'de yoğunluk 64,3 lbm/ft³. Sütün viskozitesini a) SI, b) cgs biriminde bulunuz.","st":["İngiliz birimleriyle Re'ye koy (D = 1/12 ft): $50\\,000 = \\dfrac{(64{,}3)(13{,}5)(1/12)}{\\mu}$ → $\\mu = 0{,}00145\\ \\text{lbm/(ft s)}$.","a) SI: $0{,}00145\\ \\dfrac{\\text{lbm}}{\\text{ft s}}\\times\\dfrac{0{,}4536\\ \\text{kg}}{1\\ \\text{lbm}}\\times\\dfrac{1\\ \\text{ft}}{0{,}3048\\ \\text{m}} = 2{,}16\\times10^{-3}\\ \\text{kg/(m s)}$ = Pa s.","b) cgs: $2{,}16\\times10^{-3}\\ \\dfrac{\\text{kg}}{\\text{m s}}\\times\\dfrac{1000\\ \\text{g}}{\\text{kg}}\\times\\dfrac{1\\ \\text{m}}{100\\ \\text{cm}} = 2{,}16\\times10^{-2}\\ \\text{g/(cm s)}$ (Poise) = 2,16 cP."],"ans":"µ = 2,16 × 10⁻³ Pa s = 2,16 × 10⁻² P = 2,16 cP."},{"id":"Örnek 4","src":"s.22–25","key":true,"q":"İngiliz sisteminde h = 0,0128 G^0,8 (G: lbm/ft² h, h: BTU/ft² h °F). Bu eşitliği SI biriminde ifade ediniz.","st":["Sabitin birimi: $\\dfrac{\\text{BTU}}{\\text{ft}^2\\,\\text{h °F}}\\Big/\\Big(\\dfrac{\\text{lbm}}{\\text{ft}^2\\,\\text{h}}\\Big)^{0{,}8} = \\dfrac{\\text{BTU}}{\\text{h}^{0{,}2}\\,\\text{ft}^{0{,}4}\\,\\text{lbm}^{0{,}8}\\,\\text{°F}}$.","Her birimi çevir: $0{,}0128\\times\\dfrac{1055\\ \\text{J}}{\\text{BTU}}\\times\\Big(\\dfrac{1\\ \\text{h}}{3600\\ \\text{s}}\\Big)^{0{,}2}\\times\\Big(\\dfrac{1\\ \\text{ft}}{0{,}3048\\ \\text{m}}\\Big)^{0{,}4}\\times\\Big(\\dfrac{1\\ \\text{lbm}}{0{,}4536\\ \\text{kg}}\\Big)^{0{,}8}\\times\\dfrac{1{,}8\\ \\text{°F}}{\\text{K}}$.","Çarpanlar: $1055\\times0{,}1944\\times1{,}6084\\times1{,}8822\\times1{,}8 = 1117{,}7$; $0{,}0128\\times1117{,}7 = 14{,}31$.","Sabitin SI birimi: J/(s^0,2 m^0,4 kg^0,8 K)."],"ans":"SI'da h = 14,31 G^0,8 (G: kg/m² s, h: W/m² K)."}],"tuzak":["Toplanan/çıkarılan terimlerin aynı birimde olması gerektiğini unutmak (Van der Waals'ın anahtarı bu).","Re'de çapı inch olarak bırakmak: 1 in = 1/12 ft (veya 0,0254 m) yapılmalı.","Üslü birimlerde (G^0,8) çevirme katsayısının da üssünü almayı unutmak.","cP ile P'yi karıştırmak: 1 P = 100 cP, 1 cP = 1 mPa s.","Dittus–Boelter'deki 0,023 birimsizdir; ama R, h = 0,0128 G^0,8'deki sabit gibi sabitlerin birimi vardır."],"tekrar":["Eşitliğin iki tarafı aynı birimde olmalı; hesaptan önce kontrol et.","Q = h A ΔT: W/(m² K) · m² · K = W.","Van der Waals: b = m³/kmol, a = N m⁴/kmol², R = J/(kmol K). Kural: toplanan terimler aynı birimde.","Re = DVρ/µ, Nu = hD/k, Pr = cpµ/k, Fo = αt/L², Bi = hL/k: hepsi birimsiz.","Süt örneği: µ = 0,00145 lbm/(ft s) = 2,16 × 10⁻³ Pa s = 2,16 cP.","Dittus–Boelter Nu = 0,023 Re^0,8 Pr^0,3: sabit birimsiz.","R = 8,314 J/(mol K) = 1,987 cal/(mol K) = 0,0821 L atm/(mol K).","h = 0,0128 G^0,8 (İngiliz) → h = 14,31 G^0,8 (SI)."],"kisa":["İki taraf aynı birim; toplanan terimler aynı birim.","Re, Nu, Pr, Fo, Bi birimsiz.","µ: 1 cP = 10⁻³ Pa s.","h = 0,0128 G^0,8 → 14,31 G^0,8."],"hap":["Bi = hL/k ile Nu = hD/k aynı görünür; Bi'de k katının, Nu'da k akışkanın ısıl iletkenliğidir.","Viskozitenin SI birimi kg/(m s) = Pa s.","Boyutsuz eşitlikteki sabit her birim sisteminde aynıdır.","Birimli sabitin değeri birim sistemine göre değişir (R = 8,314 / 1,987 / 0,0821)."]},{"no":5,"hafta":"Hafta 5","grp":"Gıdaların fiziksel nitelikleri","slayt":"ked-05-konsantrasyon.pdf","title":"Konsantrasyon","ozet":"Molarite, normalite, molalite, ppm, ppb, %w/v, %w/w, Briks, kütle ve mol fraksiyonu. Stok çözeltiden çözelti hazırlama ve \"mevzuata uygun mu?\" soruları.","konu":[{"h":"Gıdaların fiziksel nitelikleri","p":["Önemli fiziksel özellikler: **yoğunluk, özgül ısı, viskozite, ısıl iletkenlik katsayısı**. Hepsi gıdanın kimyasal bileşimine bağlı olarak belli sınırlar içinde değişir. En doğru değer **deneysel** yolla bulunur; geliştirilmiş eşitlikler yaklaşık değer verir.","İşlemede önemli fiziksel değişkenler: **konsantrasyon, sıcaklık, basınç**.","**Konsantrasyon:** belli bir hacim ya da ağırlıktaki çözeltide çözünen madde miktarının ölçüsü."]},{"h":"Hacme dayalı: Molarite (M)","p":["1 L **çözeltide** çözünmüş maddenin mol sayısı (mol/L)."],"f":["M = \\frac{n}{V_{\\text{çözelti}}}\\qquad n = \\frac{W}{M_w}"],"p2":["W: çözünen madde (g), Mw: mol kütlesi (g/mol), V: **çözeltinin toplam hacmi** (L). En önemli nokta: payda çözücünün değil, çözeltinin hacmi."],"anim":"molar"},{"h":"Hacme dayalı: Normalite (N)","p":["1 L çözeltide bulunan çözünmüş maddenin **eşdeğer gram sayısı**."],"f":["N = \\frac{\\text{eşdeğer gram sayısı}}{1\\ \\text{L çözelti}} \\qquad \\text{eşdeğer gram} = \\frac{M_w}{\\text{T.D.}} \\qquad N = M\\times\\text{T.D.}"],"p2":["**T.D. (tesir değerliği):** asit ve bazlarda H⁺ veya OH⁻ sayısı; yükseltgen/indirgenlerde alınan-verilen elektron sayısı. NaOH → 1, H₂SO₄ → 2, H₃PO₄ → 3."]},{"h":"Kütleye dayalı: Molalite (m)","p":["1000 g **çözücüde** çözünmüş maddenin mol sayısı (mol/kg çözücü)."],"f":["m = \\frac{n}{1000\\ \\text{g çözücü}}"],"p2":["Molaritede **çözeltinin hacmi**, molalitede **çözücünün miktarı** önemlidir. Sınavın sevdiği fark bu."]},{"h":"ppm ve ppb","p":["Seyreltik çözeltilerde ve gıdalardaki kalıntı, katkı, toksin miktarlarında kullanılır."],"f":["\\text{ppm} = \\frac{\\text{mg}}{\\text{kg}} = \\frac{\\mu\\text{g}}{\\text{g}} \\qquad \\text{ppb} = \\frac{\\mu\\text{g}}{\\text{kg}} = \\frac{\\text{ng}}{\\text{g}} \\qquad 1\\ \\text{ppm} = 1000\\ \\text{ppb}"],"p2":["Su için 1 L ≈ 1 kg olduğundan **mg/L ≈ ppm**. Yoğunluk verilmişse önce hacmi kütleye çevir: 500 mL × 1,02 g/mL = 510 g = 0,51 kg.","Mantık: miktarı **1 kg'a (ya da 1 L'ye) ölçekle**. 80 mL'de 1 mg → 1 L'de 1 × 1000/80 = 12,5 mg → 12,5 ppm."],"anim":"ppm"},{"h":"Yüzde ifadeleri ve Briks","li":["**%w/v (kütle/hacim):** 100 mL çözeltideki çözünen gram. %10 (w/v) şeker çözeltisi: 100 mL'de 10 g şeker.","**%w/w (kütle/kütle):** 100 g çözeltideki çözünen gram. Ticari asitler (HCl, H₂SO₄) böyle verilir. Stok asitten hacim almak için **yoğunluk** gerekir.","**Briks (°Bx):** 100 g sulu çözeltide çözünmüş madde gramı (kütle/kütle). Çözünenlerin çoğu uçucu olmayan şeker, asit ve tuzlardır. Refraktometreyle (el, dijital, Abbe) ölçülür.","Briks; hammaddenin ürüne uygunluğunu, ürün kalitesini ve **mikrobiyolojik stabiliteyi** gösterir."]},{"h":"Birimsiz terimler: kütle ve mol fraksiyonu","f":["X_A = \\frac{W_A}{W_A + W_B}\\qquad Y_A = \\frac{n_A}{n_A + n_B}\\qquad \\sum X_i = \\sum Y_i = 1"],"p2":["Kütle oranı $W_A/W_C$, mol oranı $n_A/n_C$ (üçüncü bir madde C varsa ona göre). Fraksiyonların toplamı 1 olmalı; bunu kontrol olarak kullan."]},{"h":"Gaz karışımının ortalama mol kütlesi","f":["\\bar M = \\sum Y_i M_i \\quad(\\text{mol fraksiyonuyla}) \\qquad \\frac{1}{\\bar M} = \\sum \\frac{X_i}{M_i}\\quad(\\text{kütle fraksiyonuyla})"],"p2":["Dikkat: slayt 45'te bu iki formülün etiketleri yer değiştirmiş yazılmış. Doğrusu yukarıdaki: Y (mol) ile çarpıp toplarsın, X (kütle) ile bölüp toplarsın. Slayttaki örnek (s.47–48) doğru etiketle çözülmüş; iki yol da 28,75 g/mol verir."]}],"formul":[["Mol sayısı","n = W/M_w"],["Molarite","M = n/V_{\\text{çözelti}}\\ (\\text{mol/L})"],["Normalite","N = M\\times \\text{T.D.}"],["Eşdeğer gram","M_w/\\text{T.D.}"],["Molalite","m = n/\\text{kg çözücü}"],["ppm","\\text{mg/kg} \\approx \\text{mg/L (su)}"],["ppb","\\mu\\text{g/kg} = \\text{ppm}\\times1000"],["Briks","°\\text{Bx} = \\frac{\\text{çözünen (g)}}{\\text{çözelti (g)}}\\times100"],["Kütle fraksiyonu","X_A = W_A/\\sum W"],["Mol fraksiyonu","Y_A = n_A/\\sum n"],["Ortalama mol kütlesi","\\bar M = \\sum Y_i M_i,\\quad 1/\\bar M = \\sum X_i/M_i"],["Hacim ↔ kütle","\\rho = m/V"]],"ornek":[{"id":"Örnek 1","src":"s.11–13","key":true,"q":"100 mL çözeltide 4,9 g H₂SO₄ var (Mw = 98 g/mol). Molarite ve normaliteyi bulunuz.","st":["$n = 4{,}9/98 = 0{,}05$ mol. $M = 0{,}05/0{,}1\\ \\text{L} = 0{,}5$ M.","H₂SO₄ için T.D. = 2. Eşdeğer gram = 98/2 = 49 g. Eşdeğer sayısı = 4,9/49 = 0,1.","$N = 0{,}1/0{,}1\\ \\text{L} = 1$ N (ya da $N = M\\times2 = 1$)."],"ans":"0,5 M ve 1 N."},{"id":"Örnek 2","src":"s.15–17","q":"%28 (w/w) stok HCl çözeltisinin molalitesini bulunuz (Mw = 36,5).","st":["100 g çözelti: 28 g HCl + 72 g su.","1000 g suya ölçekle: $28\\times1000/72 = 388{,}9$ g HCl.","$n = 388{,}9/36{,}5 = 10{,}65$ mol → 10,65 mol/1000 g su."],"ans":"10,65 m."},{"id":"Örnek 3","src":"s.20–22","key":true,"anim":"ppm","q":"Ca²⁺ konsantrasyonunu ppm olarak bulunuz: a) 1 L suda 1 mg, b) 100 mL suda 1 mg, c) 80 mL suda 1 mg.","st":["a) 1 mg / 1 L (= 1 kg) = **1 ppm**.","b) 100 mL'yi 1 L'ye çıkarmak için ×10: 10 mg/L = **10 ppm**.","c) ×1000/80 = ×12,5: 12,5 mg/L = **12,5 ppm**."],"ans":"1 ppm, 10 ppm, 12,5 ppm."},{"id":"Örnek 4","src":"s.24–26","q":"Aynı çözeltilerdeki Ca²⁺ konsantrasyonunu ppb olarak bulunuz.","st":["ppb = ppm × 1000 (1 mg = 1000 µg).","a) 1000 ppb, b) 10 000 ppb, c) 12 500 ppb."],"ans":"1000, 10 000 ve 12 500 ppb."},{"id":"Örnek 5","src":"s.29–33","key":true,"q":"Stok HCl (%28 w/w, ρ = 1,15 g/cm³) kullanarak 2 L 0,4 M HCl çözeltisi hazırlayınız (Mw = 36,5).","st":["Gereken saf HCl: $n = 0{,}4\\times2 = 0{,}8$ mol → $W = 0{,}8\\times36{,}5 = 29{,}2$ g.","Stok %28'lik: $100\\ \\text{g stok} : 28\\ \\text{g HCl} = X : 29{,}2$ → $X = 104{,}3$ g stok.","Tartmak yerine hacim al: $V = m/\\rho = 104{,}3/1{,}15 = 90{,}7$ mL.","90,7 mL stok 2 L'lik ölçü balonuna alınır, çizgiye kadar damıtık su ile tamamlanır, ağzı kapatılıp 10 kez ters çevrilerek karıştırılır."],"ans":"90,7 mL stok HCl alınıp 2 L'ye tamamlanır."},{"id":"Örnek 6","src":"s.36–37","q":"74 g nar suyunda 11,65 g şeker, 1,05 g organik asit, 0,17 g organik asit tuzu var. Briksi yaklaşık hesaplayınız.","st":["Suda çözünen madde: $11{,}65 + 1{,}05 + 0{,}17 = 12{,}87$ g.","Briks $= 12{,}87/74\\times100 = 17{,}39$ °Bx."],"ans":"≈ 17,4 °Bx (100 g nar suyunda 17,39 g çözünür madde)."},{"id":"Örnek 7","src":"s.40–41","q":"%28 (w/w) stok HCl çözeltisindeki HCl'nin mol fraksiyonunu bulunuz.","st":["100 g çözelti: 28 g HCl → $28/36{,}5 = 0{,}767$ mol; 72 g su → $72/18 = 4$ mol.","$Y_{HCl} = 0{,}767/(0{,}767 + 4) = 0{,}161$."],"ans":"Y(HCl) = 0,161."},{"id":"Örnek 8–9","src":"s.42–48","q":"%21 oksijen ve %79 azottan (kütlece) oluşan havanın kütle ve mol fraksiyonlarını ve ortalama mol kütlesini bulunuz (O₂ = 32, N₂ = 28).","st":["100 g hava: 21 g O₂, 79 g N₂. Kütle fraksiyonları: X(O₂) = 0,21, X(N₂) = 0,79. Kontrol: toplam 1.","Mol: $21/32 = 0{,}65625$, $79/28 = 2{,}82143$, toplam 3,47768 mol. Y(O₂) = 0,189, Y(N₂) = 0,811.","a) Mol fraksiyonuyla: $\\bar M = 0{,}1887\\times32 + 0{,}8113\\times28 = 28{,}75$.","b) Kütle fraksiyonuyla: $1/\\bar M = 0{,}21/32 + 0{,}79/28$ → $\\bar M = 28{,}75$ g/mol."],"ans":"X = 0,21 / 0,79; Y = 0,189 / 0,811; ortalama mol kütlesi 28,75 g/mol."},{"id":"Örnek 10","src":"s.49–53","key":true,"q":"43 kg şeker (sakaroz, Mw = 342) 100 kg suda çözülüyor; şurubun yoğunluğu 1127 kg/m³. Konsantrasyonu a) kütle fraksiyonu, b) % w/v, c) mol fraksiyonu, d) molarite olarak bulunuz.","st":["a) $X = 43/(100+43) = 0{,}30$ → %30 (w/w).","b) Şurup hacmi $V = 143/1127 = 0{,}1269\\ \\text{m}^3 = 126{,}9$ L. $43\\ \\text{kg}/126{,}9\\ \\text{L} = 0{,}339$ kg/L = 339 g/L → %33,9 (w/v).","c) $n_{su} = 100\\,000/18 = 5555{,}6$ mol, $n_{şeker} = 43\\,000/342 = 125{,}7$ mol. $Y = 125{,}7/(5555{,}6+125{,}7) = 0{,}022$.","d) $M = 125{,}7\\ \\text{mol}/126{,}9\\ \\text{L} = 0{,}99$ M."],"ans":"%30 w/w; %33,9 w/v; Y = 0,022; 0,99 M."}],"tuzak":["Molaritede paydaya **çözücü** hacmi yazmak. Payda çözeltinin hacmi; molalitede ise çözücünün kütlesi.","ppm hesabında yoğunluğu kullanmamak. \"Yoğunluğu 1,02 g/mL olan 500 mL\" → 0,51 kg.","ppb'yi ppm ile karıştırmak: ppb = µg/kg; 1 ppm = 1000 ppb.","Normalitede T.D.'yi unutmak (H₂SO₄ için 2).","Stok asit sorusunda saf HCl kütlesini direkt hacme çevirmek. Sıra: mol → saf g → stok g (÷ %28) → mL (÷ ρ).","Briksi çözünen/çözücü diye hesaplamak; payda **çözeltinin** kütlesi."],"tekrar":["M = n/V(çözelti, L); N = M × T.D. (H₂SO₄: 2); m = n/kg çözücü.","ppm = mg/kg ≈ mg/L; ppb = µg/kg = ppm × 1000. Önce 1 kg'a/1 L'ye ölçekle.","Yoğunluk verilirse hacmi kütleye çevir: m = ρV.","%w/v: 100 mL çözeltide g; %w/w: 100 g çözeltide g; Briks: 100 g çözeltide çözünen g.","X = kütle fraksiyonu, Y = mol fraksiyonu; toplamları 1.","Ortalama mol kütlesi: Σ Y·M veya 1/Σ(X/M). Hava (kütlece %21 O₂): 28,75 g/mol.","Stok HCl: 0,8 mol → 29,2 g → 104,3 g stok → 90,7 mL.","Şurup 43 kg/100 kg su, ρ 1127: %30 w/w, %33,9 w/v, Y 0,022, 0,99 M."],"kisa":["Molarite: çözelti hacmi. Molalite: çözücü kütlesi.","N = M × T.D.","ppm = mg/kg, ppb = µg/kg, ×1000.","Briks = 100 g çözeltideki çözünen g."],"hap":["%28 HCl → 10,65 molal; mol fraksiyonu 0,161.","80 mL'de 1 mg → 12,5 ppm = 12 500 ppb.","Çiğ sütte aflatoksin sınırı (slayt ödevi): 0,05 ppb.","Briks refraktometreyle ölçülür ve mikrobiyolojik stabilite hakkında fikir verir.","Normalite her zaman molariteye eşit ya da büyüktür (T.D. ≥ 1)."]},{"no":6,"hafta":"Hafta 6","grp":"Gıdaların fiziksel nitelikleri","slayt":"ked-06-yogunluk.pdf","title":"Yoğunluk ve türleri","ozet":"Yoğunluk, tablodan interpolasyon, katı / partikül / kitle yoğunluğu, porozite, bileşimden gıda yoğunluğu, elma neden yüzer, bağıl yoğunluk ve özgül hacim.","konu":[{"h":"Yoğunluk","f":["\\rho = \\frac{m}{V}"],"tbl":{"head":["Sistem","Birim"],"rows":[["SI","kg/m³"],["İngiliz","lbm/ft³"],["mks","kg/L"],["cgs","g/cm³ (g/mL)"]]},"p2":["Yoğunluk **sıcaklıkla değişir** (sıcaklık ↑ → hacim ↑ → yoğunluk ↓). Bu yüzden yoğunluk verilirken sıcaklık da belirtilir.","Gazlarda basınç da etkilidir; gaz yoğunlukları standart koşullarda (**0 °C ve 760 mmHg**) verilir.","Pratik çevirme: 1 g/cm³ = 1 kg/L = 1000 kg/m³ = 62,43 lbm/ft³."]},{"h":"İnterpolasyon","p":["Tabloda aranan değer doğrudan yoksa, iki komşu değerin değişim eğilimine göre (doğrusal kabul ederek) hesaplanır."],"tbl":{"head":["T (°C)","0","3,98","5","10","15","40","80","100"],"rows":[["ρ su (g/cm³)","0,99987","1,00000","0,99999","0,99973","0,99913","0,99224","0,97183","0,95838"]]},"f":["y = y_1 + \\frac{x - x_1}{x_2 - x_1}\\,(y_2 - y_1)"],"p2":["Slayttaki 3 adım: (1) 10 → 15 °C'de 5 birim artışta yoğunluk 6 × 10⁻⁴ azalıyor. (2) 12 °C için 2 birim artış → orantı: x = 2,4 × 10⁻⁴. (3) ρ(12 °C) = 0,99973 − 0,00024 = 0,99949 g/cm³."],"anim":"interp"},{"h":"Gıdaların yoğunluğu neye bağlı?","li":["En iyi yöntem **deneysel** ölçümdür; geliştirilen eşitlikler tam doğru vermez.","Bileşime, özellikle **su ve suda çözünen madde** içeriğine bağlıdır. Sütte yağ ↑ → yoğunluk ↓; protein, şeker, tuz ↑ → yoğunluk ↑.","**Hücreler arası boşluklar:** çözünen madde nedeniyle sudan ağır olması beklenen birçok meyve ve sebze, içindeki hava yüzünden sudan hafiftir."]},{"h":"Katı, partikül ve kitle yoğunluğu","tbl":{"head":["Tür","Hacme dahil olan","Not"],"rows":[["Katı yoğunluğu (solid)","Sadece katı madde; **tüm boşluklar hariç**","Belirtilmemişse verilen yoğunluk katı yoğunluktur"],["Partikül yoğunluğu (particle)","Katı + **partikül içi** boşluklar; partiküller arası hariç","Tek tanenin yoğunluğu gibi"],["Kitle yoğunluğu (bulk)","Katı + partikül içi + **partiküller arası** tüm boşluklar","Depo/çuval/silo hacmi hesabında kullanılır"]]},"f":["\\rho_{\\text{katı}} \\;\\ge\\; \\rho_{\\text{partikül}} \\;\\ge\\; \\rho_{\\text{kitle}} \\qquad \\text{Porozite} = 1 - \\frac{\\rho_{\\text{kitle}}}{\\rho_{\\text{katı}}}"],"p2":["Porozite: katı madde tarafından doldurulmayan hacim oranı. Kitle yoğunluğu düşük ürünler boşluklarında daha fazla hava barındırır.","Yağ ve tuz dışındaki birçok gıda bileşeninin katı yoğunluğu **1,4–1,6 g/cm³** arasındadır."],"anim":"yogunluk"},{"h":"Bileşenlerin katı yoğunlukları (Tablo 3)","tbl":{"head":["Bileşen","g/cm³","Bileşen","g/cm³"],"rows":[["Glukoz","1,56","Sitrik asit","1,54"],["Sakaroz","1,59","Yağ","0,90"],["Nişasta","1,50","Tuz","2,16"],["Selüloz","1,27–1,61","Su","1,00"],["Protein","1,4","Etil alkol","0,79"]]}},{"h":"Bileşimden gıda yoğunluğu","p":["Gıdayı bileşenlerinin karışımı say: toplam kütle ÷ toplam hacim. Her bileşenin hacmi = kütlesi / yoğunluğu."],"f":["\\rho_{\\text{gıda}} = \\frac{\\sum W_i}{\\sum \\dfrac{W_i}{\\rho_i}}"],"p2":["Elma (%85 su, %14,4 şeker, %0,4 yağ, %0,2 protein) için 1057 kg/m³ çıkar. Sudan ağır ama **elma suda yüzer**, çünkü hücreleri arasında çok hava vardır; partikül yoğunluğu 1000 kg/m³'ün oldukça altındadır.","Depo hacmi hesaplanırken **kitle yoğunluğu** kullanılır. Elma 544–608, havuç 640, turunçgil 768, üzüm 368, şeftali 608, domates 672, soğan 640–736 kg/m³.","Tahıllar: buğday katı 1409–1430, kitle 790–819; arpa 1374–1415 / 565–650; yulaf 1350–1378 / 358–511; pirinç 1358–1386 / 561–591 kg/m³."]},{"h":"Bağıl yoğunluk ve özgül hacim","f":["\\text{sp-gr} = \\frac{\\rho_{\\text{madde}}}{\\rho_{\\text{su}}}\\ (\\text{birimsiz}) \\qquad v = \\frac{1}{\\rho}\\ (\\text{m}^3/\\text{kg})"],"p2":["Katı ve sıvılarda referans **4 °C'deki su** (en yüksek yoğunluk, 1000 kg/m³). Gazlarda referans **kuru hava**: 0 °C ve 1 atm'de 1,293 kg/m³, bağıl yoğunluğu 1.","Bağıl yoğunluk iki yoğunluğun oranı olduğu için birimsizdir. Gazın bağıl yoğunluğu, havanın kaç katı ağır olduğunu gösterir."]}],"formul":[["Yoğunluk","\\rho = m/V"],["Çevirme","1\\ \\text{g/cm}^3 = 1000\\ \\text{kg/m}^3 = 62{,}43\\ \\text{lbm/ft}^3"],["İnterpolasyon","y = y_1 + \\frac{x-x_1}{x_2-x_1}(y_2-y_1)"],["Gıda yoğunluğu","\\rho = \\sum W_i \\big/ \\sum (W_i/\\rho_i)"],["Porozite","\\varepsilon = 1 - \\rho_{\\text{kitle}}/\\rho_{\\text{katı}}"],["Bağıl yoğunluk","\\text{sp-gr} = \\rho/\\rho_{\\text{ref}}"],["Özgül hacim","v = 1/\\rho"],["Kuru hava (0 °C, 1 atm)","\\rho = 1{,}293\\ \\text{kg/m}^3,\\ v = 0{,}773\\ \\text{m}^3/\\text{kg}"]],"ornek":[{"id":"Örnek 1","src":"s.6–10","key":true,"anim":"interp","q":"Saf suyun 12 °C'deki yoğunluğunu tablodan interpolasyonla bulup a) SI, b) İngiliz biriminde yazınız. (10 °C: 0,99973; 15 °C: 0,99913 g/cm³)","st":["10 → 15 °C (5 birim): yoğunluk $0{,}99973 - 0{,}99913 = 6\\times10^{-4}$ azalıyor.","10 → 12 °C (2 birim): $x = 2\\times6\\times10^{-4}/5 = 2{,}4\\times10^{-4}$.","$\\rho_{12} = 0{,}99973 - 0{,}00024 = 0{,}99949$ g/cm³.","a) × 1000 → 999,49 kg/m³. b) × 62,43 → 62,40 lbm/ft³."],"ans":"999,49 kg/m³ = 62,40 lbm/ft³."},{"id":"Örnek 2","src":"s.19–22","key":true,"q":"%85 su, %14,4 şeker, %0,4 yağ, %0,2 protein içeren elmanın yoğunluğunu SI biriminde bulunuz (ρ: su 1, şeker 1,59, yağ 0,9, protein 1,4 g/cm³).","st":["Belirtilmediği için katı yoğunluk istenir. Baz: 100 g elma.","Toplam hacim: $85/1 + 14{,}4/1{,}59 + 0{,}4/0{,}9 + 0{,}2/1{,}4 = 85 + 9{,}057 + 0{,}444 + 0{,}143 = 94{,}64$ cm³.","$\\rho = 100/94{,}64 = 1{,}057$ g/cm³ = **1057 kg/m³**.","Yorum: sudan ağır ama elma yüzer; hücreler arası hava partikül yoğunluğunu 1000'in altına düşürür."],"ans":"1057 kg/m³."},{"id":"Örnek 3","src":"s.29–30","q":"Amonyak gazının yoğunluğu 0,769 kg/m³. Bağıl yoğunluğunu bulunuz (kuru hava 1,293 kg/m³).","st":["$\\text{sp-gr} = 0{,}769/1{,}293 = 0{,}595$."],"ans":"0,595 (havadan hafif)."},{"id":"Örnek 4","src":"s.32–33","q":"Standart koşullarda (0 °C, 760 mmHg) kuru havanın özgül hacmini bulunuz.","st":["$v = 1/\\rho = 1/1{,}293 = 0{,}773$ m³/kg."],"ans":"0,773 m³/kg."},{"id":"Ek alıştırma","src":"tablo s.25","ek":true,"q":"Buğdayın katı yoğunluğu 1420 kg/m³, kitle yoğunluğu 800 kg/m³ ise porozitesi nedir? 10 ton buğday için kaç m³ silo hacmi gerekir?","st":["Porozite $= 1 - 800/1420 = 0{,}437$ → hacmin %43,7'si hava.","Silo hacmi **kitle yoğunluğuyla**: $10\\,000/800 = 12{,}5$ m³."],"ans":"Porozite ≈ 0,44; 12,5 m³ silo."}],"tuzak":["Hangi yoğunluk olduğu söylenmemişse **katı yoğunluk** kabul edilir.","Depo/silo hacmi için kitle yoğunluğu kullanılır, katı yoğunluk değil.","Karışım yoğunluğunda yoğunlukları yüzdelerle ağırlıklı ortalamak YANLIŞ. Doğrusu hacimleri toplamak: Σm / Σ(m/ρ).","İnterpolasyonda azalan değerlerde işareti şaşırmak (sıcaklık ↑, su yoğunluğu ↓).","Bağıl yoğunluğa birim yazmak; birimsizdir."],"tekrar":["ρ = m/V; sıcaklık ↑ → ρ ↓. Gazlar 0 °C, 760 mmHg'de verilir.","İnterpolasyon: y = y₁ + (x−x₁)/(x₂−x₁)·(y₂−y₁). Su 12 °C: 0,99949 g/cm³.","Katı ≥ partikül ≥ kitle. Katı: boşluk yok; partikül: tane içi boşluk dahil; kitle: hepsi dahil.","Porozite = 1 − ρkitle/ρkatı. Depo hacmi → kitle yoğunluğu.","Gıda yoğunluğu = Σm / Σ(m/ρ). Elma 1057 kg/m³ ama hava yüzünden yüzer.","Bağıl yoğunluk: sıvı/katı için 4 °C su, gaz için kuru hava (1,293 kg/m³). Birimsiz.","Özgül hacim v = 1/ρ; kuru hava 0,773 m³/kg."],"kisa":["ρ = m/V, sıcaklığı belirt.","Katı > partikül > kitle; porozite = 1 − ρk/ρs.","Gıda ρ = Σm/Σ(m/ρ).","sp-gr birimsiz; v = 1/ρ."],"hap":["Su en yoğun 3,98 ≈ 4 °C'de: 1,00000 g/cm³.","Gıda bileşenlerinin çoğu (yağ, tuz hariç) 1,4–1,6 g/cm³.","Yağ 0,90 · tuz 2,16 · sakaroz 1,59 · protein 1,4 g/cm³.","Elma katı yoğunluğu 1057 kg/m³; kitle yoğunluğu 544–608 kg/m³.","Amonyak bağıl yoğunluğu 0,595."]},{"no":7,"hafta":"Hafta 7","grp":"Gıdaların fiziksel nitelikleri","slayt":"ked-07-sicaklik-isi-basinc.pdf","title":"Sıcaklık, ısı ve basınç","ozet":"Dört sıcaklık skalası ve ΔT tuzağı, ısı birimleri (kcal, BTU, J), basınç birimleri, mutlak–efektif–vakum ve P = ρgh tank soruları.","konu":[{"h":"Sıcaklık ve termal denge","p":["Bir maddedeki moleküllerin hareketinden gelen **ortalama kinetik enerji** o maddenin sıcaklığını oluşturur (içsel enerji).","Sıcak ve soğuk iki cisim temas edince bir süre sonra aynı sıcaklığa gelir: **termal denge**. Bu sırada ısı **sıcaktan soğuğa** akar; sıcaklık ısının akış yönünü belirler.","Termal denge dokunarak değil, üçüncü bir cisimle (termometre) ölçülerek belirlenir. Sıcaklıkla ölçülebilir biçimde değişen materyale **termometrik obje** denir (sıvı hacmi, metal çubuk boyu, sabit hacimdeki gazın basıncı). Değişim doğrusal olmalı.","Skalanın **sabit noktası suyun üçlü noktasıdır**: 0,01 °C = 273,16 K."]},{"h":"Dört skala","tbl":{"head":["Skala","Kim, ne zaman","Su donma / kaynama","Mutlak sıfır","Not"],"rows":[["Fahrenheit (°F)","G. D. Fahrenheit, 1724","32 / 212 (180 parça)","−459,67 °F","0 °F'ın fiziksel anlamı yok; ABD ve İngiltere"],["Celsius (°C)","A. Celsius, 1742","0 / 100 (100 parça)","−273,15 °C","Santigrat; ondalık temelli, bilimde F'nin yerini aldı"],["Kelvin (K)","Lord Kelvin, 1854","273,15 / 373,15","0 K","Derece işareti yok; termodinamiğin mutlak skalası"],["Rankine (R)","W. J. M. Rankine, 1859","491,67 / 671,67","0 R","Derece işareti yok; ABD/İngiliz mühendisliği"]]},"p2":["Kelvin ve Rankine **mutlak skalalardır**: sıfırları mutlak sıfırdır, negatif değer yoktur. Mutlak sıfır, atom ve moleküllerin en düşük enerjide olduğu, teorik olarak ulaşılamayan en düşük sıcaklıktır."],"anim":"termometre"},{"h":"Çevirme formülleri ve ΔT tuzağı","f":["°\\text{F} = 1{,}8\\,°\\text{C} + 32 \\qquad °\\text{C} = \\tfrac{5}{9}(°\\text{F} - 32)","\\text{K} = °\\text{C} + 273{,}15 \\qquad \\text{R} = °\\text{F} + 459{,}67","\\Delta T(\\text{K}) = \\Delta T(°\\text{C}) \\qquad \\Delta T(\\text{R}) = \\Delta T(°\\text{F}) \\qquad \\Delta T(°\\text{F}) = 1{,}8\\,\\Delta T(°\\text{C})"],"p2":["**En büyük hata:** bir sıcaklık **değerini** çevirmek ile bir sıcaklık **farkını** (ΔT) çevirmek farklı şeylerdir. 90 °F sıcaklık 32,2 °C'dir; ama \"90 °F ısıtıldı\" 50 °C ısıtıldı demektir. Farkta +32 ya da +273 yoktur, sadece ölçek (1,8) vardır.","Neden 1,8? Donma–kaynama arası F'de 180, C'de 100 parça: 180/100 = 1,8."]},{"h":"Isı","p":["Isı bir enerji şeklidir: **bir sistem ile çevresi arasında yalnızca sıcaklık farkından dolayı akan enerji.**","**1 kcal:** 1 kg suyun sıcaklığını 14,5 °C'den 15,5 °C'ye çıkaran ısı. **1 BTU:** 1 lbm suyu 63 °F'tan 64 °F'a ısıtan ısı. Mekanik işin ısı eşdeğerini ilk ölçen J. P. Joule'dür; SI'da ısı birimi **Joule**."],"tbl":{"head":["","kJ","kcal","BTU"],"rows":[["1 kJ","1","0,238","0,948"],["1 kcal","4,186","1","3,968"],["1 BTU","1,055","0,252","1"]]}},{"h":"Basınç birimleri","p":["Birim alana etki eden kuvvet. Boyutu: kütle / (zaman² · uzunluk). SI'da N/m² = **Pa**; İngiliz sisteminde lbf/in² = **psi**."],"li":["**Teknik atmosfer (at):** 1 kg'lık kütlenin 1 cm²'ye etkisi: 1 at = 1 kgf/cm² = 1 kp/cm². (kp: standart kütlenin standart yerçekimindeki ağırlığı, 1 kp = 1 kgf.)","**Standart (fiziksel) atmosfer (atm):** yoğunluğu 13,595 g/mL olan 760 mm cıva sütununun yaptığı basınç.","**1 atm = 760 mmHg = 10,33 m su sütunu = 14,696 psi = 1,01325 bar = 101 325 Pa = 1,0332 kgf/cm².**","Pa çok küçük olduğu için kPa (10³), bar (10⁵) ve MPa (10⁶) kullanılır. 1 bar ≈ 1 atm."]},{"h":"Mutlak, efektif (manometre) basınç ve vakum","f":["P_{\\text{mutlak}} = P_{\\text{atm}} + P_{\\text{efektif}} \\qquad \\text{Vakum} = P_{\\text{atm}} - P_{\\text{mutlak}}"],"li":["**Mutlak basınç:** mükemmel vakum (sıfır basınç) başlangıç alınarak ölçülür; \"abs\" yazılır: 1 atm (abs), bar (abs).","**Efektif (manometre) basınç:** atmosfer basıncı sıfır kabul edilerek ölçülür. Manometreler bunu gösterir.","**Vakum:** mutlak basınç 1 atm'den düşükse; vakum çoğunlukla mmHg ile verilir.","Basınç verilirken abs mı eff mi belirtilmeli. **Belirtilmemişse efektif (manometre) basınç** anlaşılır: \"sistemde 2 atm\" = 2 atm manometre.","İngiliz: **psia** = mutlak, **psig** = manometre (gauge). Teknik atmosfer: **ata** = mutlak, **atü** = efektif."],"anim":"basinc"},{"h":"Hidrostatik basınç: P = ρgh","f":["P = \\rho\\, g\\, h \\qquad (g = 9{,}81\\ \\text{m/s}^2)"],"p2":["Sıvının tabana yaptığı basınç **yalnızca yüksekliğe ve yoğunluğa bağlıdır**, tabanın çapından (alanından) bağımsızdır.","**Ağzı açık tankta** sıvının üstüne atmosfer de bastırır: $P_{\\text{taban}} = P_{\\text{atm}} + \\rho g h$. Kapalı tankta üstteki gaz basıncı eklenir. En yüksek basınç tabandadır.","Hacim–kütle bağı: silindirde $V = \\pi r^2 h$, $m = \\rho V$."],"anim":"tank"}],"formul":[["°C → °F","°\\text{F} = 1{,}8\\,°\\text{C} + 32"],["°F → °C","°\\text{C} = (°\\text{F} - 32)/1{,}8"],["Kelvin","\\text{K} = °\\text{C} + 273{,}15"],["Rankine","\\text{R} = °\\text{F} + 459{,}67"],["Fark","\\Delta °\\text{F} = 1{,}8\\,\\Delta °\\text{C},\\ \\ \\Delta\\text{K} = \\Delta°\\text{C}"],["Isı birimleri","1\\ \\text{kcal} = 4{,}186\\ \\text{kJ},\\ 1\\ \\text{BTU} = 1{,}055\\ \\text{kJ} = 0{,}252\\ \\text{kcal}"],["Standart atmosfer","1\\ \\text{atm} = 760\\ \\text{mmHg} = 101\\,325\\ \\text{Pa} = 14{,}696\\ \\text{psi}"],["","1\\ \\text{atm} = 1{,}01325\\ \\text{bar} = 10{,}33\\ \\text{m ss} = 29{,}92\\ \\text{inHg}"],["Teknik atmosfer","1\\ \\text{at} = 1\\ \\text{kgf/cm}^2 = 98\\,100\\ \\text{Pa}"],["Mutlak","P_{abs} = P_{atm} + P_{eff}"],["Vakum","P_{vak} = P_{atm} - P_{abs}"],["Hidrostatik","P = \\rho g h"],["Kuvvet birimi","1\\ \\text{lbf} = 4{,}4482\\ \\text{N}"]],"ornek":[{"id":"Örnek 1 (sıcaklık)","src":"s.22–24","key":true,"anim":"termometre","q":"40 °C'deki su 95 °C'ye ısıtılıyor. a) Başlangıç ve son sıcaklık K? b) °F? c) Su °C, °F ve K olarak kaç derece ısınmıştır?","st":["a) $40 + 273 = 313$ K, $95 + 273 = 368$ K.","b) $1{,}8(40) + 32 = 104$ °F, $1{,}8(95) + 32 = 203$ °F.","c) $\\Delta T = 55$ °C = **55 K** (aynı ölçek) = $1{,}8\\times55 =$ **99 °F**. Kontrol: 368 − 313 = 55 K, 203 − 104 = 99 °F."],"ans":"313 → 368 K; 104 → 203 °F; ΔT = 55 °C = 55 K = 99 °F."},{"id":"Örnek 1 (basınç)","src":"s.40–41","key":true,"q":"Ankara'da atmosfer basıncı 690 mmHg. Bunu kPa ve lbf/in² olarak bulunuz.","st":["$690\\ \\text{mmHg}\\times\\dfrac{101\\,325\\ \\text{Pa}}{760\\ \\text{mmHg}}\\times\\dfrac{1\\ \\text{kPa}}{1000\\ \\text{Pa}} = 92{,}0$ kPa.","$690\\times\\dfrac{14{,}696}{760} = 13{,}34$ lbf/in² (slaytta 13,32 yazıyor; hesap 13,34 veriyor)."],"ans":"92 kPa ≈ 13,3 psi."},{"id":"Örnek 2–3","src":"s.42–45","q":"a) 690 mmHg'yi 14,696 değerini kullanmadan lbf/in²'ye çeviriniz. b) 1,0332 kgf/cm² teknik atmosferi fiziksel atmosfere çeviriniz.","st":["a) Zincir: mmHg → atm → Pa → N/m² → kg/(m s²) → lbm → lbf (1 lbf = 32,174 lbm ft/s²) → ft → in. Sonuç yine 13,3 lbf/in².","b) $1{,}0332\\ \\tfrac{\\text{kgf}}{\\text{cm}^2}\\times\\dfrac{9{,}81\\ \\text{N}}{1\\ \\text{kgf}}\\times\\dfrac{10^4\\ \\text{cm}^2}{1\\ \\text{m}^2} = 101\\,357$ Pa; $\\div 101\\,325 = 1{,}000$ atm."],"ans":"a) ≈ 13,3 psi; b) 1,0332 kgf/cm² = 1 atm."},{"id":"Ödev","src":"s.46","q":"1 lbf'nin 4,4482 N'a eşit olduğunu gösteriniz.","st":["1 lbf: 1 lbm kütleye standart yerçekimi ivmesinin (32,174 ft/s²) uyguladığı kuvvet.","$1\\ \\text{lbm} = 0{,}45359$ kg, $32{,}174\\ \\text{ft/s}^2 = 9{,}80665$ m/s².","$F = ma = 0{,}45359\\times9{,}80665 = 4{,}4482$ N."],"ans":"1 lbf = 0,45359 kg × 9,80665 m/s² = 4,4482 N."},{"id":"Örnek 6","src":"s.55–56","key":true,"anim":"basinc","q":"Hermetik kutuda 0,605 atm (abs) basınç ölçülmüş. Kutudaki vakum miktarı nedir?","st":["$P_{vak} = P_{atm} - P_{abs} = 1 - 0{,}605 = 0{,}395$ atm.","mmHg: iç basınç $760\\times0{,}605 = 459{,}8$ mmHg; vakum $760 - 459{,}8 = 300{,}2$ mmHg."],"ans":"0,395 atm = 300,2 mmHg vakum."},{"id":"Örnek 7","src":"s.57–59","key":true,"q":"20 inHg vakum altında çalışan evaporatörün mutlak basıncını a) SI, b) İngiliz biriminde bulunuz.","st":["$P_{atm} = 760\\ \\text{mmHg} = 29{,}92$ inHg. $P_{abs} = 29{,}92 - 20 = 9{,}92$ inHg.","a) $9{,}92\\ \\text{inHg}\\times\\dfrac{25{,}4\\ \\text{mm}}{\\text{in}}\\times\\dfrac{101\\,325\\ \\text{Pa}}{760\\ \\text{mmHg}} = 33\\,593$ Pa = 33,6 kPa (abs).","b) $9{,}92\\times14{,}696/29{,}92 = 4{,}872$ psia."],"ans":"33,6 kPa (abs) = 4,872 psia."},{"id":"Örnek 8","src":"s.61–63","key":true,"anim":"tank","q":"Süt dolu tankın tabanında 0,2 atm basınç oluşturan süt yüksekliği nedir? (ρ = 1,028 g/cm³)","st":["$\\rho = 1028$ kg/m³. $P = 0{,}2\\times101\\,325 = 20\\,265$ Pa.","$h = P/(\\rho g) = 20\\,265/(1028\\times9{,}81) = 2{,}01$ m."],"ans":"h ≈ 2,01 m."},{"id":"Örnek 9","src":"s.65–66","q":"Yoğunluğu 0,915 g/cm³ olan zeytinyağı, çapı 2 m olan küre şeklindeki tanka dolduruluyor. Tankın en üstündeki basınç 75 kPa. Tanktaki en yüksek basıncı bulunuz.","st":["En yüksek basınç tabanda. Yükseklik = kürenin çapı = 2 m.","$P_{max} = 75\\,000 + (2)(915)(9{,}81) = 75\\,000 + 17\\,952 = 92\\,952$ Pa."],"ans":"≈ 92,95 kPa."},{"id":"Örnek 10","src":"s.67–70","key":true,"anim":"tank:domates","q":"Çapı 1 m olan ağzı açık tanka %6 KM'li domates suyu (ρ = 1025 kg/m³) doldurulacak. Tankta basınç 120 kPa'ı geçmemeli. En fazla kaç kg domates suyu doldurulabilir?","st":["Ağız açık → üstte atmosfer var: $P_{\\text{dom}} = 120 - 101{,}325 = 18{,}675$ kPa.","$h = 18\\,675/(1025\\times9{,}81) = 1{,}86$ m.","$V = \\pi r^2 h = 3{,}14\\times0{,}5^2\\times1{,}86 = 1{,}46$ m³.","$m = \\rho V = 1025\\times1{,}46 = 1497$ kg."],"ans":"≈ 1497 kg (tam değerlerle 1495 kg)."}],"tuzak":["ΔT'yi çevirirken +32 eklemek. Fark: ΔK = Δ°C, Δ°F = 1,8 Δ°C.","Kelvin ve Rankine'de derece işareti kullanmak (doğrusu K, R; °K değil).","Ağzı açık tankta atmosfer basıncını unutmak (Örnek 10'un püf noktası).","Hiçbir şey yazmıyorsa basıncın **efektif** olduğunu unutmak.","Vakumu mutlak basınç sanmak: vakum = atm − mutlak.","P = ρgh'da yoğunluğu g/cm³ bırakmak; kg/m³ olmalı (× 1000).","Hidrostatik basıncın taban alanına bağlı olduğunu sanmak; bağlı değil."],"tekrar":["Sıcaklık = ortalama kinetik enerji; ısı sıcaktan soğuğa akar; sabit nokta suyun üçlü noktası (0,01 °C = 273,16 K).","°F = 1,8 °C + 32; K = °C + 273,15; R = °F + 459,67. Mutlak skalalar K ve R.","ΔT: 1 °C = 1 K = 1,8 °F = 1,8 R. 40 → 95 °C: 55 K, 99 °F.","1 kcal = 4,186 kJ; 1 BTU = 1,055 kJ = 0,252 kcal.","1 atm = 760 mmHg = 10,33 m ss = 14,696 psi = 1,01325 bar = 101 325 Pa; 1 at = 1 kgf/cm².","Pabs = Patm + Peff; vakum = Patm − Pabs. Belirtilmemişse efektif. psia/psig, ata/atü.","P = ρgh, tabandan bağımsız. Açık tank: Patm + ρgh.","Süt 0,2 atm → 2,01 m. Domates suyu 120 kPa sınır → 1,86 m, ≈ 1497 kg."],"kisa":["°F = 1,8 °C + 32; K = °C + 273.","ΔT'de +32 yok: Δ°F = 1,8 Δ°C.","1 atm = 760 mmHg = 101,325 kPa = 14,696 psi.","Pabs = Patm + Peff; vakum = Patm − Pabs.","P = ρgh (+ Patm açık tankta)."],"hap":["−40 °C = −40 °F (iki skalanın kesiştiği tek nokta).","1 atm = 10,33 m su sütunu = 760 mm cıva sütunu.","Kelvin ve Rankine'de negatif değer yoktur.","\"2 atm basınç var\" → 2 atm manometre basıncı (efektif).","1 lbf = 4,4482 N.","Sıvı basıncı tankın çapına bağlı değildir."]},{"no":8,"hafta":"Hafta 8","grp":"Kütle denkliği","slayt":"ked-08-kutle-denkligi.pdf","title":"Kütle denkliği: ilkeler ve temel örnekler","ozet":"Maddenin sakınımı, kararlı/kararsız proses, sistem türleri, baz seçimi, akış diyagramı; toplam ve bileşen denklikleriyle kurutma, seyreltme, evaporatör, karıştırma ve kristalizasyon.","konu":[{"h":"Kütle denkliği ne işe yarar?","p":["Bir üretimde sisteme giren ve çıkan akışları izlemek, her akıştaki maddelerin miktarını bulmak. Ne kadar hammadde, ne kadar ürün, ne kadar su, ne kadar atık, ürünün bileşimi ne?"],"li":["Reçete düzenleme (formülasyon).","Karıştırılan maddelerden oluşan yeni karışımdaki her maddenin konsantrasyonunu bulma.","Randıman saptama.","Mekanik ayırma sistemlerinin etkinliğini belirleme."]},{"h":"İlke: maddenin sakınımı","f":["\\text{Sisteme akış} = \\text{Sistemden dışarı akış} + \\text{Sistemde birikim}"],"li":["**Kararlı (yatışkın, steady state) proses:** birikim = 0 → giren = çıkan. Sınav sorularının neredeyse hepsi böyle.","**Kararsız (unsteady state) proses:** birikim ≠ 0; sistemdeki konsantrasyonlar zamanla değişir. Birçok sürekli işlemde başlangıçta kısa bir kararsızlık dönemi olur, sonra kararlı hale gelir."]},{"h":"Sistem ve sınırları","p":["İlk iş: işlemi diyagrama aktarıp **sistemin sınırlarını** çizmek. Sınır gerçek (tank duvarı) ya da hayali olabilir (tank–boru–pompa–valf sisteminde yalnız valfi seçersen valfin etrafındaki hayali sınır)."],"tbl":{"head":["Sistem","Kütle transferi","Isı alışverişi","Örnek"],"rows":[["Açık","Var","Olabilir","Tank + borular, evaporatör"],["Kapalı","Yok","Olabilir","Sıvı akışına izin vermeyen tank"],["İzole","Yok","Yok","Çevresiyle hiçbir alışverişi olmayan sistem"],["Adyabatik","–","Yok","Isı alışverişi olmayan sistem"],["İzotermal","–","Var","Reaksiyon sabit sıcaklıkta, çevreyle ısı alışverişi var"]]},"anim":"sistemler"},{"h":"Baz seçimi ve kesikli/sürekli sistemler","p":["**Baz:** sonucun hangi miktara göre tanımlanacağıdır; giren/çıkan miktarlar verilmediğinde özellikle önemlidir. Evaporatörde meyve suyu konsantre ediliyorsa 4 baz seçilebilir:"],"li":["Evaporatöre giren meyve suyu miktarı (100 kg, 1000 kg…).","Evaporatörden çıkan konsantre miktarı.","Giren meyve suyunun çıkan konsantreye oranı (4:1, 5:1).","Çıkan konsantrenin giren meyve suyuna oranı (1:4, 1:5)."],"p2":["**Kesikli (batch):** belli miktar madde sisteme bir defada girer, aynı miktar çıkar. **Kesiksiz (sürekli):** belli bir zaman dilimi baz alınır (ör. 1 saat) ve kesikli gibi çözülür. İkisinde de ilkeler aynıdır."]},{"h":"Çözüm reçetesi","li":["Sistemdeki tüm akımların (giren ve çıkan) miktarlarını ve bileşimlerini belirle.","**Madde akış diyagramını** çiz; akımları oklarla işaretle, sistem sınırını çiz.","Bilinen bütün verileri diyagramın üstüne yaz.","Gerekirse bir **baz** seç (100 kg, 1 saat…).","**Toplam** ve **bireysel madde** denkliklerini yaz. Her bilinmeyen için bir eşitlik gerekir.","Eşitlikleri art arda çöz; önce tek bilinmeyenli olanı (genelde bir bileşen denkliği) çöz.","Kontrol et: giren toplam = çıkan toplam mı?"],"p2":["Miktarlar **kütle** birimiyle, konsantrasyonlar **kütle fraksiyonu** olarak yazılır. Hacimle verilen miktar yoğunlukla kütleye çevrilir, çünkü işlem sırasında hacim değişebilir (hacimler toplanmaz!)."]},{"h":"Proses akış diyagramı ve madde akış diyagramı","p":["İşlem basamaklarını kutucuklar içinde art arda yazınca **proses akış diyagramı** elde edilir. Domates salçası (sıcak işleme): yıkama → ayıklama → parçalama → ısıtma → palper (pulp) → evaporatör (salça) → 93 °C'ye ısıtma → sıcak dolum ve kapatma → soğutma → kartonlama → depolama (11 basamak).","Randıman hesabı için **madde akış diyagramı** yeterlidir: sadece madde kaybı/değişimi olan basamaklar (ayıklama → atık 1, palper → atık 2, evaporatör → su) gösterilir. Diğer basamaklarda madde kaybı yoktur. Kaç kutu salça çıkacağı sorulursa dolum basamağı da eklenir."]},{"h":"Toplam ve bireysel madde denklikleri","p":["**Toplam kütle denkliği:** giren akışların toplam kütlesi = çıkan akışların toplam kütlesi. Bileşenler ayrı ayrı dikkate alınmaz. Evaporatör: $P = S + K$ (pulp = su + salça).","**Bireysel madde denkliği:** her madde (kuru madde, şeker, yağ, asit, su…) ayrı ayrı. Kaç madde varsa o kadar eşitlik yazılabilir. Seri eşitlikler peş peşe çözülür."],"f":["\\underbrace{F}_{\\text{giren}} = \\underbrace{W}_{\\text{su}} + \\underbrace{C}_{\\text{konsantre}} \\qquad F\\,x_F = W\\cdot 0 + C\\,x_C"],"p2":["**Kısa yol:** yalnız su giriyor ya da çıkıyorsa (kurutma, evaporasyon, sulandırma) kuru madde denkliği tek başına yeter: $m_1 x_1 = m_2 x_2$. Su akımında kuru madde 0, kristal akımında sakaroz 1 (%100) alınır."],"anim":"evaporator"},{"h":"Alt sistemler","p":["Birden çok ünite varsa her ünitenin etrafına ayrı sınır çizip **alt sistem denklikleri** yazılabilir. Tüm sistem denkliği + alt sistem denklikleri bilinmeyenleri çözmeye yeter.","**Sıcak hava kurutucu:** tüm sistem $W + A = \\text{Nemli ılık hava} + D$; hava alt sistemi $A + \\text{Su} = \\text{Nemli ılık hava}$; kuruyan madde alt sistemi $W = \\text{Su} + D$.","**Cut-back (portakal suyu):** taze sudan bir kısmı (E) evaporatörde 68 °Bx'e konsantre edilir, aroma zayıf olduğu için kalan taze su (A) eklenerek 45 °Bx yapılır. Toplam $P = W + C_{45}$; dağıtıcı $P = E + A$; evaporatör $E = W + C_{68}$; karıştırıcı $C_{68} + A = C_{45}$."]}],"formul":[["Genel denklik","\\text{Giren} = \\text{Çıkan} + \\text{Birikim}"],["Kararlı proses","\\text{Birikim} = 0 \\Rightarrow \\text{Giren} = \\text{Çıkan}"],["Evaporatör (toplam)","F = W + C"],["Evaporatör (KM)","F x_F = C x_C"],["Kısa yol","m_1 x_1 = m_2 x_2"],["Karıştırma (toplam)","A + B = M"],["Karıştırma (bileşen)","A x_A + B x_B = M x_M"],["Kristalizasyon","F = X + Y,\\quad F x_F = X(1) + Y x_{doy}"],["Kütle fraksiyonu","x_A = \\frac{\\text{A bileşeninin kütlesi}}{\\text{karışımın toplam kütlesi}}"]],"ornek":[{"id":"Örnek 2","src":"s.25–26","q":"Evaporatöre giren domates pulpu (P) salça (K) olarak çıkıyor, bir kısım su (S) buharlaşıyor. Kararlı proses için toplam kütle dengesi eşitliğini yazınız.","st":["$P = S + K + \\text{Birikim}$; kararlı proseste birikim = 0.","$P = S + K$."],"ans":"P = S + K."},{"id":"Örnek 3","src":"s.27–30","q":"Kurutucu W kg/dak yaş madde ve A kg/dak sıcak hava ile besleniyor, kurutulmuş madde D kg/dak ile çıkıyor. Toplam ve alt sistem denkliklerini yazınız.","st":["Tüm sistem: $W + A = \\text{Nemli ılık hava} + D$.","Hava alt sistemi: $A + \\text{Su} = \\text{Nemli ılık hava}$.","Kuruyan madde alt sistemi: $W = \\text{Su} + D$."],"ans":"W + A = Nemli hava + D; A + Su = Nemli hava; W = Su + D."},{"id":"Örnek 4","src":"s.31–34","q":"Cut-back işleminde (68 °Bx konsantreye taze portakal suyu eklenerek 45 °Bx yapılması) ana sistem ve alt sistem denkliklerini yazınız.","st":["Toplam: $P = W + C_{45}$.","Dağıtıcı: $P = E + A$.","Evaporatör: $E = W + C_{68}$.","Karıştırıcı: $C_{68} + A = C_{45}$."],"ans":"Dört eşitlik yukarıda."},{"id":"Örnek 5","src":"s.38–40","key":true,"q":"%8,1 kuru madde içeren 7 kg materyal kurutularak kuru madde %90'a çıkarılıyor. Kurutulmuş materyalin kütlesi nedir?","st":["1. yol: kuru madde $7\\times0{,}081 = 0{,}567$ kg; kurumuş materyalde bu %90 → $X = 0{,}567/0{,}9 = 0{,}63$ kg.","2. yol: toplam $7 = W + X$; KM: $7(0{,}081) = W(0) + X(0{,}9)$ → $X = 0{,}63$ kg, $W = 6{,}37$ kg."],"ans":"0,63 kg (6,37 kg su uzaklaşır)."},{"id":"Örnek 6","src":"s.41–43","key":true,"q":"%66 şeker içeren 25 kg şurup su ile seyreltilerek %11'lik şurup yapılıyor. Elde edilen şurup kaç kg?","st":["Toplam: $25 + X = Y$. Şeker: $25(0{,}66) + X(0) = Y(0{,}11)$.","$Y = 16{,}5/0{,}11 = 150$ kg; $X = 125$ kg su."],"ans":"150 kg seyreltik şurup (125 kg su eklenir)."},{"id":"Örnek 7","src":"s.44–46","key":true,"anim":"evaporator","q":"Evaporatörde saatte 500 kg su uzaklaştırılıyor. %12 KM'li meyve suyu giriyor, %45 KM'li konsantre çıkıyor. Konsantre üretim hızı nedir?","st":["Baz: 1 saat. Toplam: $F = C + 500$ (1).","KM: $0{,}12F = 0{,}45C$ → $F = 3{,}75C$ (2).","(2)'yi (1)'e koy: $3{,}75C = C + 500$ → $C = 500/2{,}75 = 181{,}8$ kg.","$F = 681{,}8$ kg/h."],"ans":"C = 181,8 kg/h (F = 681,8 kg/h)."},{"id":"Örnek 8","src":"s.47–50","key":true,"anim":"karistirma","q":"%12 KM ve %0,8 asit içeren meyve suyuna %66 şekerli şurup eklenerek %15 KM'li meyve suyu yapılacak. Gereken şurup miktarı ve son ürünün asit içeriği nedir?","st":["Baz: 100 kg meyve suyu. Toplam: $100 + X = Y$ (1).","KM: $100(0{,}12) + X(0{,}66) = Y(0{,}15)$ (2). Asit: $100(0{,}008) = Y z$ (3).","(1)'i (2)'ye: $12 + 0{,}66(Y-100) = 0{,}15Y$ → $0{,}51Y = 54$ → $Y = 105{,}9$ kg.","$X = 5{,}9$ kg şurup. $z = 0{,}8/105{,}9 = 0{,}0076$ → %0,76 asit."],"ans":"100 kg meyve suyu başına 5,9 kg şurup; asit %0,76."},{"id":"Örnek 9","src":"s.51–54","key":true,"anim":"kristal","q":"%75 sakarozlu 100 kg sıcak şurup kristalizatörde 15 °C'ye soğutuluyor. 15 °C'de doymuş çözelti %66 sakaroz içeriyor. Oluşan kristal ve şurup miktarı nedir? (Kristaller kuru çıkıyor.)","st":["Toplam: $100 = X + Y$ (1). Sakaroz: $100(0{,}75) = X(1) + Y(0{,}66)$ (2).","(2) → $X = 75 - 0{,}66Y$; (1)'e koy: $100 = 75 - 0{,}66Y + Y$ → $0{,}34Y = 25$ → $Y = 73{,}5$ kg.","$X = 26{,}5$ kg kristal.","2. yol (su denkliği): su kristale girmez: $100(0{,}25) = Y(0{,}34)$ → $Y = 73{,}5$ kg."],"ans":"≈ 26,5 kg kristal, 73,5 kg doymuş şurup."},{"id":"Örnek 10","src":"s.55","key":true,"q":"%85 sakaroz ve %1 suda çözünen inert safsızlık içeren 100 kg konsantre şeker çözeltisi kristalize ediliyor. Santrifüjden çıkan konsantre çözelti %60 sakaroz içeriyor. Kristal fraksiyonunun %20'si, çıkan çözeltiyle aynı bileşimde yapışık çözeltidir. Kristal fraksiyonu ve konsantre çözelti miktarları nedir?","st":["Kristal fraksiyonu = K (içinde 0,8K saf kristal + 0,2K çözelti), konsantre çözelti = S.","Toplam: $100 = K + S$.","Sakaroz: $85 = 0{,}8K(1) + 0{,}2K(0{,}60) + S(0{,}60) = 0{,}92K + 0{,}6S$.","$S = 100 - K$ koy: $85 = 0{,}92K + 60 - 0{,}6K$ → $0{,}32K = 25$ → $K = 78{,}125$ kg.","$S = 21{,}875$ kg. (Saf kristal 62,5 kg.)"],"ans":"78,125 kg kristal fraksiyonu, 21,875 kg konsantre şeker çözeltisi (slayttaki cevapla aynı)."}],"tuzak":["Su akımında kuru maddeyi 0 almayı, kristal akımında sakarozu 1 (%100) almayı unutmak.","Hacimleri toplamak: karıştırmada litreler toplanmaz, kütleler toplanır.","Baz seçmeden saat/gün karışıklığına düşmek: sürekli proseste \"1 saat\" baz al, sonunda istenen süreye çevir.","Bilinmeyen sayısı kadar eşitlik kurmamak. 2 bilinmeyen → 2 eşitlik (toplam + bir bileşen).","Seyreltmede konsantrasyonun suyla değil, **toplam** ürünle oranlandığını unutmak: Y(0,11), X(0,11) değil.","Sonucu kontrol etmemek: giren toplam = çıkan toplam mı?"],"tekrar":["Giren = Çıkan + Birikim; kararlı proseste birikim 0.","Açık: kütle ve ısı geçebilir; kapalı: yalnız ısı; izole: hiçbiri. Adyabatik: ısı yok; izotermal: sabit sıcaklık, ısı alışverişi var.","Baz: 100 kg ya da 1 saat. Kesikli = bir defada; sürekli = zaman bazı.","Reçete: diyagram çiz → verileri yaz → baz seç → toplam + bileşen denklikleri → çöz → kontrol et.","Miktarlar kütle, konsantrasyonlar kütle fraksiyonu. Hacim → ρ ile kütle.","Kurutma 7 kg %8,1 → %90: 0,63 kg. Seyreltme 25 kg %66 → %11: 150 kg.","Evaporatör 500 kg/h su, %12 → %45: C = 181,8 kg/h.","Karıştırma 100 kg %12 + şurup %66 → %15: 5,9 kg şurup, asit %0,76.","Kristalizasyon 100 kg %75 → doymuş %66: 26,5 kg kristal."],"kisa":["Giren = Çıkan (kararlı).","Diyagram + baz + toplam + bileşen denkliği.","Su akımında KM = 0, kristalde sakaroz = 1.","Kütleler toplanır, hacimler toplanmaz."],"hap":["İzole sistemde ne kütle ne ısı geçer.","Adyabatik: ısı alışverişi yok.","Her bilinmeyen için bir eşitlik gerekir.","Randıman için madde akış diyagramında sadece kayıp/değişim olan basamaklar yeter.","Cut-back: 68 °Bx konsantre + taze su → 45 °Bx, aroma için."]},{"no":9,"hafta":"Hafta 9","grp":"Kütle denkliği","slayt":"ked-09-proses-gruplari.pdf","title":"Gıda proseslerinde kütle denkliği","ozet":"Mekanik ön işlemler (vişne, mandarin, salça), şeker şurubu hazırlama, meyve suyu ayarlama ve rekonstitüsyon, nektar soruları. Tablo 1 ve Tablo 2 ile çalışma.","konu":[{"h":"Mekanik ön işlemler","p":["Meyve ve sebzelerde yıkama, kabuk soyma, boylama, parçalama, ayıklama, sap ayırma, çekirdek çıkarma. Yıkama, boylama ve parçalamada kütle transferi ya yok ya da çok azdır. **Kabuk soyma, ayıklama, sap ayırma ve çekirdek çıkarmada** daha fazla kayıp vardır.","Kütle denkliği **yenilebilir kısım, yan ürün ve atık** arasında kurulur. Kayıplar çoğunlukla \"%x kayıp\" diye verilir: o basamağa **giren** miktarın %x'i."],"anim":"salca"},{"h":"Meyve suyu, nektar ve meyveli içecek","li":["Meyve suyu ilke olarak doğal haliyle ambalajlanır. Ama bazıları içilebilir değildir: **vişne çok asitli, kayısı ve şeftali çok kıvamlı**. Su, şeker, asit eklenir.","**Nektar:** meyve oranı %25–99. **Meyveli içecek:** meyve oranı %10–24.","Mevsim başında briksi düşük portakal suyuna konsantre eklenerek briks yükseltilebilir (standardizasyon).","Konsantrelerin geri sulandırılmasına **rekonstitüsyon** denir. Su, şeker, asit ilavesinin genel adı **ayarlama**.","Rekonstitüsyonda **demineralize su**, diğer ilavelerde en az içme suyu kalitesinde su kullanılır.","Şeker kristal ya da **%65–70 briksli şurup** olarak eklenir (şurup önerilir). Asit çoğunlukla **kristal sitrik asit**; önceden %50'lik çözelti yapılabilir."]},{"h":"Tablolarla çalışma","li":["Tüm hesaplar **kütle** üzerinden yapılır; hacim verilmişse yoğunlukla kütleye çevrilir.","**Tablo 1 (şeker şurubu tablosu, 20 °C):** konsantre ve şurupların yoğunluğu, 1 L şurup için gereken şeker (g) ve su (mL), 1 L suya eklenecek şeker ve oluşan şurup hacmi.","**Tablo 2 (meyve suyu tablosu, 20 °C):** meyve suyu, pulp ve nektarların yoğunluğu ile kuru madde (%) ilişkisi.","Tabloda tam değer yoksa **interpolasyon** yapılır (Hafta 6)."],"tbl":{"head":["Tablo 1 (seçme)","Yoğunluk (kg/L)","1 L şurup: şeker (g)","1 L şurup: su (mL)","1 L suya şeker (g)","Oluşan şurup (mL)"],"rows":[["%60","1,2864","771,9","514,5","1500,3","1943,6"],["%65","1,3163","855,6","460,7","1857,1","2170,6"],["%66","1,3224","872,8","449,6","1941,3","2224,2"],["%68","1,3347","907,6","427,1","2125,0","2341,4"],["%70","1,3472","943,0","404,2","2333,0","2474,0"],["%72","1,3598","979,1","380,7","2571,8","2626,7"]]}},{"h":"Nektar ayarlama: üç denklem","f":["\\text{Toplam: } F + X + Y (+Z) = N","\\text{Kuru madde: } F x_F + X x_{\\text{şurup}} (+ Z) = N x_N","\\text{Asit: } F a_F (+ Z) = N a_N"],"p2":["F: meyve suyu/konsantre/pulp, X: şeker şurubu (ya da kristal şeker, x = 1), Y: su, Z: sitrik asit (x = 1, asit = 1), N: nektar.","Püf noktası: **asit denkliği çoğu zaman tek bilinmeyenlidir**; önce onu çöz, nektar miktarını bul, sonra KM denkliğinden şurubu, en son toplamdan suyu.","Pulp oranı sınırı verilmişse (şeftali nektarında en az %40 pulp) nektar miktarı doğrudan oradan bulunur."],"anim":"nektar"}],"formul":[["Kayıp","\\text{Atık} = \\text{giren}\\times\\%\\text{kayıp}"],["Randıman","\\text{Ürün} = \\text{hammadde}\\times\\%\\text{randıman}"],["Hacim → kütle","m = \\rho V\\quad(\\rho:\\ \\text{Tablo 1/2'den})"],["Şurup (kristal şeker)","x_{\\text{şeker}} = 1"],["Asit denkliği","F a_F + Z = N a_N"],["KM denkliği","F x_F + X x_S + Z = N x_N"],["Toplam","F + X + Y + Z = N"],["Pulp oranı","N = \\text{pulp}/0{,}40\\ (\\text{şeftali})"]],"ornek":[{"id":"Örnek 1 (vişne)","src":"s.3–6","key":true,"q":"500 L vişne suyu üretilecek. Meyve suyu randımanı %85, vişne suyu yoğunluğu 1042 kg/m³. Vişnelerin sap + çekirdek oranı nedir?","st":["Kütle: $500\\ \\text{L} = 0{,}5\\ \\text{m}^3$; $0{,}5\\times1042 = 521$ kg vişne suyu.","Gereken vişne: $V = 521/0{,}85 = 613$ kg.","Toplam: $V = Ç + S + P$ → $613 = Ç + S + 521$ → $Ç + S = 92$ kg.","Oran: $92/613\\times100 = \\%15$."],"ans":"Vişnenin %15'i sap ve çekirdek."},{"id":"Örnek 2 (mandarin)","src":"s.7–10","key":true,"q":"Satsuma mandarinden (10,5 °Bx) konserve: dış kabuk soymada %20, dilim zarı soymada (kabuğu soyulmuş mandarinin) %5 kayıp. 800 kg mandarinden 1000 kg konserve; dengede şurup 18 °Bx. a) Kabuk ve dilim zarı miktarı, b) şurup miktarı, c) şurup konsantrasyonu?","st":["Kabuk: $K = 800\\times0{,}20 = 160$ kg → $T = 640$ kg soyulmuş mandarin.","Dilim zarı: $Z = 640\\times0{,}05 = 32$ kg → $M = 608$ kg.","Konserve: $M + S = 1000$ → $S = 392$ kg şurup.","KM: $608(0{,}105) + 392A = 1000(0{,}18)$ → $63{,}84 + 392A = 180$ → $A = 0{,}296$."],"ans":"a) 160 kg kabuk, 32 kg zar; b) 392 kg şurup; c) %29,6."},{"id":"Örnek 3 (salça)","src":"s.11–15","key":true,"anim":"salca","q":"%28 KM'li salça üretimi. Ayıklamada %2, palperde %8 atık. Saatte 250 kg domates işleniyor; domates ve atıkların KM'si %5. Günde kaç adet 500 g'lık kutu salça üretilir?","st":["Baz 1 h. Ayıklama: atık 1 = $250\\times0{,}02 = 5$ kg → 245 kg.","Palper: atık 2 = $245\\times0{,}08 = 19{,}6$ kg → pulp 225,4 kg.","Tüm sistem KM: $250(0{,}05) = 5(0{,}05) + 19{,}6(0{,}05) + W(0) + S(0{,}28)$ → $12{,}5 - 0{,}25 - 0{,}98 = 0{,}28S$ → $S = 40{,}25$ kg/h.","Su: $W = 225{,}4 - 40{,}25 = 185{,}15$ kg/h. Günlük: $40{,}25\\times24 = 966$ kg → $966/0{,}5 = 1932$ kutu."],"ans":"Günde 1932 kutu (24 saat çalışma)."},{"id":"Şurup 1","src":"s.26–29","key":true,"q":"%66 sakarozlu 500 L şeker şurubu için gereken şeker ve su miktarını ve şurubun kütlesini bulunuz (Tablo 1).","st":["Tablo 1, %66: 1 L şurup için 872,8 g şeker + 449,6 mL su; yoğunluk 1,3224 kg/L.","Şeker: $500\\times0{,}8728 = 436{,}4$ kg. Su: $500\\times0{,}4496 = 224{,}8$ L (kg).","Şurup kütlesi: $500\\times1{,}3224 = 661{,}2$ kg (kontrol: 436,4 + 224,8 = 661,2)."],"ans":"436,4 kg şeker, 224,8 kg su, 661,2 kg şurup."},{"id":"Şurup 2","src":"s.30–33","q":"Aynı soruyu tablo kullanmadan, sakarozun katı yoğunluğu 1,61 g/mL kabul ederek çözünüz; şurubun yoğunluğunu bulunuz.","st":["1 kg %66 şurup: 0,66 kg şeker ($0{,}66/1{,}61 = 0{,}41$ L) + 0,34 kg su (0,34 L) → 0,75 L.","500 L için: şeker $0{,}66\\times500/0{,}75 = 440$ kg, su $0{,}34\\times500/0{,}75 = 226{,}7$ kg.","Şurup $666{,}7$ kg → $\\rho = 666{,}7/500 = 1{,}333$ kg/L.","Tablodan biraz sapar; tablo deneysel olduğu için daha güvenilir (hacimler tam toplanmaz)."],"ans":"440 kg şeker, 226,7 kg su, ρ ≈ 1,333 kg/L."},{"id":"Şurup 3","src":"s.34–37","q":"750 L suya şeker eklenerek %66'lık şurup hazırlanacak. Gereken şeker, şurubun hacmi ve kütlesi?","st":["Tablo 1, %66: 1 L suya 1941,3 g şeker → 2224,2 mL şurup; ρ = 1,3224 kg/L.","Şeker: $750\\times1{,}9413 = 1456$ kg.","Hacim: $750\\times2{,}2242 = 1668{,}2$ L. Kütle: $1668{,}2\\times1{,}3224 = 2206$ kg."],"ans":"1456 kg şeker, 1668 L ve 2206 kg şurup."},{"id":"Örnek 4 (elma)","src":"s.38–43","key":true,"q":"%72 KM'li elma suyu konsantresinden %12 KM'li 10 000 L elma suyu hazırlanacak. Gereken su ve konsantre miktarlarını kg ve L olarak bulunuz.","st":["Tablo 2, %12 KM: 11,89 → 1,048 ve 12,12 → 1,049; interpolasyonla ρ = 1,0485 kg/L.","Elma suyu: $10\\,000\\times1{,}0485 = 10\\,485$ kg.","KM: $0{,}72X = 10\\,485(0{,}12)$ → $X = 1747{,}5$ kg konsantre. Tablo 1, %72: ρ = 1,3598 → $V = 1285$ L.","Toplam: $Y = 10\\,485 - 1747{,}5 = 8737{,}5$ kg = 8737,5 L su."],"ans":"1747,5 kg (1285 L) konsantre + 8737,5 kg (L) su."},{"id":"Örnek 5 (vişne nektarı)","src":"s.44–49","key":true,"anim":"nektar","q":"%16 KM, %2 asitli 4000 L vişne suyu su ve şekerle %14 KM, %0,8 asitli nektara ayarlanacak. a) %68'lik şurup ve su, b) kristal şeker kullanılırsa şeker ve su miktarı?","st":["Tablo 2 interpolasyon: ρ(%16) = 1,06552 kg/L → $4000\\times1{,}06552 = 4262{,}1$ kg.","Asit (tek bilinmeyen): $4262{,}1(0{,}02) = Z(0{,}008)$ → $Z = 10\\,655$ kg nektar.","a) KM: $4262{,}1(0{,}16) + X(0{,}68) = 10\\,655(0{,}14)$ → $X = 1191$ kg şurup. Toplam: $Y = 10\\,655 - 4262{,}1 - 1191 = 5202$ kg su.","b) Kristal şeker (x = 1): $X = 1491{,}7 - 681{,}9 = 809{,}8$ kg şeker; $Y = 10\\,655 - 4262{,}1 - 809{,}8 = 5583$ kg su."],"ans":"a) 1191 kg şurup + ≈ 5202 kg su; b) 809,8 kg şeker + ≈ 5583 kg su (10 655 kg nektar)."},{"id":"Örnek 6","src":"s.50–52","q":"%68 KM, %7,1 asitli vişne konsantresinden %65'lik şurup ve su ile 100 000 kutu (200 mL) nektar (%14 KM, %0,8 asit) hazırlanacak. Nektar (kg), konsantre (kg, L), şurup (kg, L), su (kg, L)?","st":["Nektar: $100\\,000\\times0{,}2 = 20\\,000$ L; Tablo 2 ρ(%14) ≈ 1,057 → 21 140 kg.","Asit: $0{,}071X = 21\\,140(0{,}008)$ → $X = 2382$ kg konsantre; Tablo 1 ρ(%68) = 1,3347 → 1785 L.","KM: $2382(0{,}68) + Y(0{,}65) = 21\\,140(0{,}14)$ → $Y = 2061$ kg şurup; Tablo 1 ρ(%65) = 1,3163 → 1566 L.","Su: $21\\,140 - 2382 - 2061 = 16\\,697$ kg ≈ 16 697 L."],"ans":"21 140 kg nektar; 2382 kg (1785 L) konsantre; 2061 kg (1566 L) şurup; ≈ 16 697 kg su."},{"id":"Örnek 7 (şeftali)","src":"s.53–56","key":true,"q":"%12 KM, %0,5 asitli 4500 kg şeftali pulpundan %14 KM, %0,6 asitli nektar yapılacak; şurup %66. Pulp oranı en az %40. Su, şurup, sitrik asit ve nektar miktarı?","st":["Nektar: $4500/0{,}40 = 11\\,250$ kg.","Asit: $4500(0{,}005) + Z = 11\\,250(0{,}006)$ → $Z = 67{,}5 - 22{,}5 = 45$ kg sitrik asit.","KM: $4500(0{,}12) + 0{,}66X + 45 = 11\\,250(0{,}14)$ → $0{,}66X = 990$ → $X = 1500$ kg şurup ($1500/1{,}3224 = 1134$ L).","Su: $11\\,250 - 4500 - 1500 - 45 = 5205$ kg."],"ans":"11 250 kg nektar; 1500 kg şurup; 45 kg asit; 5205 kg su."}],"tuzak":["%kaybı her zaman o basamağa **giren** miktardan hesapla (mandarinde zar kaybı 640 kg'ın %5'i, 800'ün değil).","Hacimle verilen meyve suyunu yoğunluksuz kütle saymak; Tablo 2'den ρ bul.","Konsantrenin yoğunluğunu Tablo 2'den aramak; konsantre ve şurup için **Tablo 1** kullanılır.","Nektarda önce şurubu çözmeye çalışmak. Önce **asit denkliği** (tek bilinmeyen) → nektar miktarı.","Kristal şeker kullanıldığında KM oranını 1 almayı unutmak; sitrik asit hem KM'ye hem asit denkliğine girer.","Günlük üretimde çalışma süresini sormadan 24 saat almak; soruda vardiya varsa onu kullan."],"tekrar":["Kayıplar o basamağa girenin yüzdesi. Kütle denkliği: yenilebilir + yan ürün + atık.","Vişne: 500 L × 1,042 = 521 kg; 521/0,85 = 613 kg vişne; sap + çekirdek %15.","Mandarin: 800 → 160 kabuk → 640 → 32 zar → 608; şurup 392 kg, %29,6.","Salça: 250 → 5 atık → 245 → 19,6 atık → 225,4 pulp → 40,25 kg salça/h → 1932 kutu/gün.","Nektar %25–99, meyveli içecek %10–24 meyve. Şurup %65–70; rekonstitüsyon = geri sulandırma.","Tablo 1: şurup/konsantre yoğunluğu; Tablo 2: meyve suyu yoğunluğu.","Nektar: önce asit → nektar kütlesi; sonra KM → şurup; en son toplam → su.","Elma: %72 → %12, 10 000 L: 1747,5 kg konsantre + 8737,5 kg su. Şeftali: 11 250 kg nektar, 1500 kg şurup, 45 kg asit, 5205 kg su."],"kisa":["Kayıp = girenin %'si.","Hacim → kütle: Tablo 1 (şurup/konsantre), Tablo 2 (meyve suyu).","Nektar: asit → KM → toplam.","Kristal şeker x = 1; sitrik asit x = 1."],"hap":["Nektar: meyve %25–99; meyveli içecek: %10–24.","Şurup %65–70 briks hazırlanıp filtrelenir.","Sitrik asit önceden %50'lik çözelti yapılabilir.","Rekonstitüsyonda demineralize su kullanılır.","Vişne çok asitli, kayısı ve şeftali çok kıvamlı olduğu için nektar yapılır.","Şeftali nektarında pulp en az %40."]}],"cikmis":[{"id":"Geçmiş sınav sorusu","tag":"Çıkmış","src":"sınıf defteri s.21 + tahta fotoğrafı","key":true,"anim":"cikmis","q":"Toz şeker üreten bir işletmede %16 sakaroz içeren 100 kg şeker çözeltisi evaporatörde %70 sakaroza kadar konsantre ediliyor. Sıcak şurup kristalizatörde soğutulup santrifüjleniyor. Santrifüjden çıkan doymuş şeker çözeltisi %55 sakaroz içerdiğine göre santrifüjden ayrılan şeker kristali ve doymuş çözelti miktarlarını hesaplayınız.","note":"Defterde doymuş çözelti %85 yazılmış ama tahtadaki çözümde %55 kullanılmış. %85 olamaz: konsantre zaten %70, doymuş çözelti ondan derişik çıkamaz. Doğrusu %55.","st":["Diyagram: 100 kg (%16) → evaporatör → su S + şurup K (%70) → kristalizatör → santrifüj → kristal C (%100) + doymuş çözelti M (%55).","Evaporatör alt sistemi: toplam $100 = S + K$; sakaroz $100(0{,}16) = S(0) + K(0{,}70)$ → $K = 22{,}857$ kg, $S = 77{,}143$ kg.","Santrifüj alt sistemi: toplam $22{,}857 = M + C$; sakaroz $22{,}857(0{,}70) = 16 = M(0{,}55) + C(1)$.","Taraf tarafa çıkar: $22{,}857 - 16 = 0{,}45M$ → $M = 15{,}238$ kg; $C = 7{,}619$ kg.","Kontrol (tüm sistem): $100 = S + M + C = 77{,}143 + 15{,}238 + 7{,}619 = 100$ ✓; sakaroz $16 = 0{,}55(15{,}238) + 7{,}619 = 16$ ✓."],"ans":"≈ 7,62 kg şeker kristali ve 15,24 kg doymuş şeker çözeltisi (77,14 kg su buharlaşır)."},{"id":"Sınıf sorusu: krema separatörü","tag":"Derste","src":"defter s.20","key":true,"anim":"separator","q":"Sürekli çalışan santrifüj separatörde %4 yağlı 36 000 kg süt 6 saatte işleniyor. Yağı alınmış sütte %0,5, kremada %45 yağ var. 1 saatte ayrılan yağsız süt ve krema miktarı nedir?","st":["Baz 1 saat: $36\\,000/6 = 6000$ kg süt.","Toplam: $6000 = K + S$. Yağ: $6000(0{,}04) = K(0{,}45) + S(0{,}005)$.","$240 = 0{,}45K + 0{,}005(6000 - K) = 0{,}445K + 30$ → $K = 471{,}9$ kg.","$S = 5528{,}1$ kg."],"ans":"471,9 kg/h krema, 5528,1 kg/h yağsız süt."},{"id":"Sınıf sorusu: nitrat (ppm)","tag":"Derste","src":"defter s.11","q":"Yoğunluğu 1,02 g/mL olan bir sebze suyu örneğinin 500 mL'sinde 2,75 mg nitrat bulunmuş. a) Nitrat kaç ppm? b) İzin verilen en yüksek değer 5 ppm ise örnek uygun mu?","st":["Kütle: $500\\ \\text{mL}\\times1{,}02 = 510\\ \\text{g} = 0{,}51$ kg.","ppm $= 2{,}75\\ \\text{mg}/0{,}51\\ \\text{kg} = 5{,}39$ ppm.","5,39 > 5 → **uygun değil**."],"ans":"5,39 ppm; uygun değil."},{"id":"Sınıf sorusu: pestisit (ppb)","tag":"Derste","src":"defter s.11","q":"Yoğunluğu 1,104 g/mL olan 1,5 L elma suyunda 0,12 mg pestisit bulunmuş. Kaç ppb? En fazla 100 ppb izinliyse uygun mu?","note":"Defterde kütle 1,560 kg yazılmış (76,92 ppb). Doğrusu 1,5 × 1,104 = 1,656 kg. Sonuç değişse de karar değişmiyor.","st":["Kütle: $1{,}5\\ \\text{L}\\times1{,}104\\ \\text{kg/L} = 1{,}656$ kg.","0,12 mg = 120 µg. ppb $= 120/1{,}656 = 72{,}5$ ppb.","72,5 < 100 → **uygun**."],"ans":"≈ 72,5 ppb; uygun."},{"id":"Ödev 1 (Hafta 5)","tag":"Ödev","src":"H5 s.54","q":"10 kg şeker (Mw = 342) 90 kg suda çözülüyor; şurubun yoğunluğu 1040 kg/m³. Konsantrasyonu a) °Briks, b) molar konsantrasyon, c) molalite olarak bulunuz.","st":["a) Briks $= 10/100\\times100 = 10$ °Bx.","b) $V = 100/1040 = 0{,}09615$ m³ = 96,15 L; $n = 10\\,000/342 = 29{,}24$ mol; $M = 29{,}24/96{,}15 = 0{,}304$ M.","c) Molalite $= 29{,}24\\ \\text{mol}/90\\ \\text{kg su} = 0{,}325$ m."],"ans":"10 °Bx; 0,304 M; 0,325 m."},{"id":"Ödev 2 (Hafta 5)","tag":"Ödev","src":"H5 s.55","q":"Süt örneklerindeki aflatoksini ppb olarak bulup mevzuata (çiğ sütte en fazla 0,05 ppb) uygunluğunu tartışınız. A: 1 L sütte 0,01 mg; B: 200 mL sütte 0,3 µg. Süt yoğunluğu 1,028 g/cm³.","st":["A: 1 L = 1,028 kg; 0,01 mg = 10 µg → $10/1{,}028 = 9{,}73$ ppb.","B: 200 mL = 0,2056 kg → $0{,}3/0{,}2056 = 1{,}46$ ppb.","İkisi de 0,05 ppb'nin çok üstünde → **ikisi de uygun değil**."],"ans":"A: 9,73 ppb, B: 1,46 ppb; ikisi de mevzuata aykırı."},{"id":"Ödev (Hafta 7)","tag":"Ödev","src":"H7 s.59","q":"20 inHg vakum altındaki evaporatörün mutlak basıncını, 14,696 psi değerini kullanmadan psia olarak bulunuz.","st":["$P_{abs} = 29{,}92 - 20 = 9{,}92$ inHg = 33 593 Pa (abs).","1 lbf = 4,4482 N, 1 in² = 6,4516 × 10⁻⁴ m² → 1 psi = 6894,8 Pa.","$33\\,593/6894{,}8 = 4{,}872$ psia."],"ans":"4,872 psia."}],"quiz":[["Çevresiyle hem kütle hem ısı alışverişi olmayan sistem hangisidir?",["Açık","Kapalı","İzole","Adyabatik"],2,"İzole sistemde ne kütle ne ısı geçer. Kapalıda ısı geçebilir, adyabatikte yalnız ısı yoktur.",8],["Kararlı (yatışkın) proseste aşağıdakilerden hangisi doğrudur?",["Birikim ≠ 0","Konsantrasyon zamanla değişir","Giren = Çıkan","Sistem kapalıdır"],2,"Kararlı proseste birikim sıfırdır; giren = çıkan.",8],["Yalnız ısı alışverişi olabilen, kütle transferi olmayan sistem?",["Açık","Kapalı","İzole","İzotermal"],1,"Kapalı sistemin sınırı akışı önler ama ısı geçebilir.",8],["Depo ya da silo hacmi hesaplanırken hangi yoğunluk kullanılır?",["Katı yoğunluğu","Partikül yoğunluğu","Kitle yoğunluğu","Bağıl yoğunluk"],2,"Kitle (bulk) yoğunluğu taneler arası boşlukları da içerir; depo hacmine uyan budur.",6],["Hangi yoğunluk olduğu belirtilmemişse verilen yoğunluk hangisi kabul edilir?",["Kitle","Partikül","Katı","Bağıl"],2,"Belirsizse katı yoğunluk kabul edilir.",6],["Elma, yoğunluğu ~1057 kg/m³ olmasına rağmen neden suda yüzer?",["Yağ oranı yüksek olduğu için","Hücreler arası boşluklarda hava olduğu için","Şeker suyu hafifletir","Kabuğu su geçirmez"],1,"Hücreler arası hava, partikül yoğunluğunu 1000 kg/m³'ün altına düşürür.",6],["Molaritede paydada ne vardır?",["Çözücünün kütlesi","Çözücünün hacmi","Çözeltinin hacmi","Çözeltinin kütlesi"],2,"M = mol/L çözelti. Molalitede ise kg çözücü.",5],["Molalite neye göre tanımlanır?",["1 L çözelti","1000 g çözücü","100 g çözelti","1 L çözücü"],1,"Molalite: 1000 g çözücüdeki mol sayısı.",5],["H₂SO₄ için normalite ile molarite ilişkisi?",["N = M","N = 2M","N = M/2","N = 3M"],1,"H₂SO₄ iki H⁺ verir, T.D. = 2: N = 2M.",5],["ppb neyi ifade eder?",["mg/kg","µg/kg","g/kg","ng/kg"],1,"ppb = µg/kg; ppm = mg/kg.",5],["Briks derecesi nedir?",["100 mL çözeltideki şeker gramı","100 g çözeltideki çözünmüş madde gramı","100 g sudaki şeker gramı","1 L çözeltideki mol sayısı"],1,"Briks kütle/kütle: 100 g çözeltide çözünen g.",5],["Briks hangi aletle ölçülür?",["Manometre","Refraktometre","Piknometre","Viskozimetre"],1,"El, dijital ve Abbe refraktometreleri.",5],["Sıcaklığı 40 °C'den 95 °C'ye çıkan su kaç °F ısınmıştır?",["55 °F","87 °F","99 °F","131 °F"],2,"ΔT = 55 °C × 1,8 = 99 °F. Farkta +32 yok.",7],["Hangisi mutlak sıcaklık skalasıdır?",["Celsius ve Fahrenheit","Kelvin ve Rankine","Celsius ve Kelvin","Fahrenheit ve Rankine"],1,"K ve R'nin sıfırı mutlak sıfırdır; negatif değerleri yoktur.",7],["Termometre skalalarında sabit nokta olarak ne seçilmiştir?",["Suyun kaynama noktası","Suyun donma noktası","Suyun üçlü noktası","Mutlak sıfır"],2,"Üçlü nokta: 0,01 °C = 273,16 K.",7],["Bir basınç değerinin yanında abs/eff yazmıyorsa hangisi anlaşılır?",["Mutlak","Efektif (manometre)","Vakum","Standart atmosfer"],1,"Belirtilmemişse efektif basınçtır.",7],["psig neyi gösterir?",["Mutlak basınç","Manometre basıncı","Vakum","Teknik atmosfer"],1,"g = gauge = manometre. psia = mutlak.",7],["0,605 atm (abs) basınçlı kutudaki vakum?",["0,605 atm","0,395 atm","1,605 atm","0,5 atm"],1,"Vakum = 1 − 0,605 = 0,395 atm = 300,2 mmHg.",7],["Bir tankın tabanındaki hidrostatik basınç neye bağlı değildir?",["Sıvı yüksekliği","Sıvı yoğunluğu","Yerçekimi ivmesi","Taban alanı (çap)"],3,"P = ρgh; çaptan bağımsız.",7],["1 atm hangisine eşit değildir?",["760 mmHg","101 325 Pa","14,696 psi","1 kgf/cm²"],3,"1 kgf/cm² = 1 at (teknik atmosfer) = 0,968 atm. 1 atm = 1,0332 kgf/cm².",7],["Paydasında °F olan bir birimi K'ye çevirirken sayı ne olur?",["1,8 ile bölünür","1,8 ile çarpılır","32 eklenir","273 eklenir"],1,"1/°F = 1,8/K. Sayı 1,8 ile çarpılır.",3],["1 kWh kaç J'dür?",["3600 J","3,6 × 10⁶ J","1000 J","3,6 × 10⁹ J"],1,"1 kW × 3600 s = 3,6 × 10⁶ J.",3],["Hangisi SI temel birimi değildir?",["kg","K","mol","N"],3,"N türetilmiştir: kg m s⁻².",2],["Hangisi doğru yazılmıştır?",["5 sn","20 gr","2 Lt","3 s"],3,"Saniye s, gram g, litre L.",2],["Pa'nın SI temel birimlerle karşılığı?",["kg m s⁻²","kg m² s⁻²","kg m⁻¹ s⁻²","kg m² s⁻³"],2,"Pa = N/m² = kg m⁻¹ s⁻².",2],["Mars Climate Orbiter neden kayboldu?",["Yakıt bitti","lbf·s ile N·s karıştırıldı","Sıcaklık birimi karıştı","Yazılım çöktü"],1,"Firma lbf·s, NASA N·s varsaydı.",2],["Reynolds sayısının birimi nedir?",["kg/m s","m²/s","Birimsiz","W/m² K"],2,"Re = DVρ/µ; birimler sadeleşir.",4],["Van der Waals eşitliğinde b sabitinin birimi?",["m³/kmol","N m⁴/kmol²","J/kmol K","kmol/m³"],0,"nb hacimden çıkarıldığı için m³/kmol.",4],["1 cP kaç Pa s'dir?",["1","10⁻²","10⁻³","10⁻⁶"],2,"1 cP = 1 mPa s = 10⁻³ Pa s.",4],["Kurutmada hangisi değişmez?",["Toplam kütle","Su miktarı","Kuru madde miktarı","Nem yüzdesi"],2,"Yalnız su uzaklaşır; kuru madde sabit.",1],["Kütle denkliğinde miktarlar neden hacimle değil kütleyle yazılır?",["Kütle daha kolay ölçülür","Hacimler karışımda değişebilir, toplanmaz","Hacim birimi yoktur","Hoca öyle istiyor"],1,"Karıştırmada hacimler tam toplanmaz (şurup örneği); kütle korunur.",8],["Nektarda meyve oranı?",["%10–24","%25–99","%100","%5–10"],1,"Nektar %25–99; meyveli içecek %10–24.",9],["Konsantrelerin geri sulandırılmasına ne denir?",["Ayarlama","Rekonstitüsyon","Cut-back","Standardizasyon"],1,"Rekonstitüsyon; su/şeker/asit ilavesinin genel adı ayarlama.",9],["Nektar ayarlama sorusunda genellikle önce hangi denklik çözülür?",["Toplam","Kuru madde","Asit","Su"],2,"Asit denkliği çoğunlukla tek bilinmeyenlidir; nektar miktarını verir.",9],["Meyve suyu konsantresi ve şeker şurubunun yoğunluğu hangi tablodan bulunur?",["Tablo 1 (şeker şurubu)","Tablo 2 (meyve suyu)","Su yoğunluğu tablosu","Buhar tablosu"],0,"Konsantre ve şurup → Tablo 1; meyve suyu, pulp, nektar → Tablo 2.",9]],"recete":[["Oku ve çiz","Soruyu okurken akış diyagramını çiz: kutular (ünite), oklar (akım). Her oka adını (F, W, C…) ve bilinen kütle/yüzdeleri yaz."],["Sınırı çiz","Tüm sistemin etrafına kesikli çizgi. Birden çok ünite varsa her birine ayrı alt sınır."],["Baz seç","Miktar verilmemişse 100 kg; sürekli proseste 1 saat. Hacim verilmişse ρ ile kütleye çevir."],["Bilinmeyenleri say","Kaç bilinmeyen varsa o kadar bağımsız eşitlik gerekir (toplam + bileşenler + alt sistemler)."],["Eşitlikleri yaz","Toplam: Σ giren = Σ çıkan. Bileşen: Σ (akım × kesir) giren = çıkan. Su akımında KM = 0, kristalde sakaroz = 1."],["Tek bilinmeyenliden başla","Kısa yol: yalnız su giriyor/çıkıyorsa $m_1x_1 = m_2x_2$. Nektarda asit denkliği."],["Kontrol et ve birimi yaz","Giren toplam = çıkan toplam mı? Sonucu birimiyle ve istenen süreyle (kg/h, kutu/gün) yaz, yorumla."]],"pdfs":[{"lbl":"Detaylı","t":"Detaylı konu anlatımı","d":"Bütün haftalar: konu anlatımı, tablolar, formüller, slayttaki bütün örneklerin çözümü, tuzaklar, çıkmış sorular.","href":"kaynaklar/kutle-enerji/pdf/1-detayli-konu-anlatimi.pdf","sz":"1,5 MB","pg":"42 sayfa"},{"lbl":"Orta","t":"Orta detaylı özet","d":"Her konunun özü, formüller ve sınava en çok benzeyen örneklerin çözümü. Uzun açıklamalar çıkarıldı.","href":"kaynaklar/kutle-enerji/pdf/2-orta-detayli-ozet.pdf","sz":"1,2 MB","pg":"28 sayfa"},{"lbl":"15 dakika","t":"15 dakikada tekrar","d":"Her hafta için 6–9 madde, formül kutusu ve örnek sonuçları. Sınavdan önce bir kez okumak için.","href":"kaynaklar/kutle-enerji/pdf/3-15-dakikada-tekrar.pdf","sz":"432 KB","pg":"7 sayfa"},{"lbl":"Kısa","t":"Kısa notlar","d":"Her hafta birkaç satır. Bütün ders iki sayfada.","href":"kaynaklar/kutle-enerji/pdf/4-kisa-notlar.pdf","sz":"254 KB","pg":"2 sayfa"},{"lbl":"Hap","t":"Hap bilgiler ve tuzaklar","d":"Akılda kalması gereken cümleler, sayılar ve en sık yapılan hatalar, numaralı.","href":"kaynaklar/kutle-enerji/pdf/5-hap-bilgiler.pdf","sz":"348 KB","pg":"4 sayfa"},{"lbl":"Formül","t":"Formül kâğıdı","d":"Dokuz haftanın bütün formülleri ve çevirme katsayıları.","href":"kaynaklar/kutle-enerji/pdf/6-formul-kagidi.pdf","sz":"267 KB","pg":"4 sayfa"},{"lbl":"Sorular","t":"Bütün çözümlü sorular","d":"Slayttaki bütün örnekler, derste çözülenler, ödevler ve çıkmış soru; önce soru, sonra adım adım çözüm.","href":"kaynaklar/kutle-enerji/pdf/7-cozumlu-sorular.pdf","sz":"745 KB","pg":"17 sayfa"}],"slides":[{"t":"Hafta 1 · Dersin mantığı: giren = çıkan","href":"kaynaklar/kutle-enerji/slaytlar/ked-01-giris.pdf","sz":"14 sayfa · 1,7 MB"},{"t":"Hafta 2 · Boyutlar, birim sistemleri ve SI","href":"kaynaklar/kutle-enerji/slaytlar/ked-02-birimler.pdf","sz":"32 sayfa · 6,9 MB"},{"t":"Hafta 3 · Birim çevirme","href":"kaynaklar/kutle-enerji/slaytlar/ked-03-birim-cevirme.pdf","sz":"33 sayfa · 4,0 MB"},{"t":"Hafta 4 · Boyutsal tutarlılık ve boyutsuz sayılar","href":"kaynaklar/kutle-enerji/slaytlar/ked-04-boyutsal-tutarlilik.pdf","sz":"25 sayfa · 979 KB"},{"t":"Hafta 5 · Konsantrasyon","href":"kaynaklar/kutle-enerji/slaytlar/ked-05-konsantrasyon.pdf","sz":"55 sayfa · 1,7 MB"},{"t":"Hafta 6 · Yoğunluk ve türleri","href":"kaynaklar/kutle-enerji/slaytlar/ked-06-yogunluk.pdf","sz":"33 sayfa · 1,6 MB"},{"t":"Hafta 7 · Sıcaklık, ısı ve basınç","href":"kaynaklar/kutle-enerji/slaytlar/ked-07-sicaklik-isi-basinc.pdf","sz":"70 sayfa · 1,8 MB"},{"t":"Hafta 8 · Kütle denkliği: ilkeler ve temel örnekler","href":"kaynaklar/kutle-enerji/slaytlar/ked-08-kutle-denkligi.pdf","sz":"55 sayfa · 1,9 MB"},{"t":"Hafta 9 · Gıda proseslerinde kütle denkliği","href":"kaynaklar/kutle-enerji/slaytlar/ked-09-proses-gruplari.pdf","sz":"56 sayfa · 2,5 MB"}]};
